Animancer - Adaptability 适应性#📋 目录#关注点分离 Mecanim的强制分离问题 Animancer的灵活组织 参数系统问题 参考资料 关注点分离#&ldquo;将代码分离成不同部分，每部分覆盖不同的关注点&rdquo;
好的分离： 模块化、可重用、易维护
坏的分离： 强制分离本应耦合的内容
Mecanim的强制分离问题#问题：不应该分离的被分离了#游戏逻辑（脚本） ←→ 动画逻辑（Controller） ↓ 需要紧密协作 ↓ 浪费时间协调两者示例：
// 脚本中 if (shouldAttack) { _animator.SetTrigger(&#34;Attack&#34;); } // Controller中需要： // 1. 创建&#34;Attack&#34;触发器参数 // 2. 创建Attack状态 // 3. 配置过渡条件 // 4. 两者必须保持同步！Animancer的灵活组织#1. 按功能模块组织#// 移动模块 public class MovementController : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip _walk; [SerializeField] private AnimationClip _run; void UpdateMovement(float speed) { if (speed &lt; 0.1f) _animancer.Play(_idle); else if (speed &lt; 5f) _animancer.Play(_walk); else _animancer.Play(_run); } } // 战斗模块 public class CombatController : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private AnimationClip[] _attacks; void Attack(int comboIndex) { _animancer.Play(_attacks[comboIndex]); } }2. 按角色部位组织#// 下半身动画 public class LowerBodyAnimations : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [Header(&#34;移动&#34;)] [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip _walk; [SerializeField] private AnimationClip _run; void PlayOnLayer0() { _animancer.Layers[0].Play(_walk); } } // 上半身动画 public class UpperBodyAnimations : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private AvatarMask _upperBodyMask; [Header(&#34;战斗&#34;)] [SerializeField] private AnimationClip _aim; [SerializeField] private AnimationClip _shoot; void Start() { _animancer.Layers[1].SetMask(_upperBodyMask); } void PlayOnLayer1() { _animancer.Layers[1].Play(_aim); } }3. 按武器类型组织#[System.Serializable] public class WeaponAnimations { public AnimationClip Idle; public AnimationClip Draw; public AnimationClip[] Attacks; public AnimationClip Block; } public class WeaponSystem : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private WeaponAnimations _sword; [SerializeField] private WeaponAnimations _bow; [SerializeField] private WeaponAnimations _staff; private WeaponAnimations _currentWeapon; void EquipSword() { _currentWeapon = _sword; _animancer.Play(_currentWeapon.Draw); } void Attack() { _animancer.Play(_currentWeapon.Attacks[0]); } }参数系统问题#Mecanim参数的三大缺陷#1. 触发器滞后问题#场景： 玩家快速按攻击键
// Mecanim _animator.SetTrigger(&#34;Attack&#34;); // 问题： // - 如果当前正在播放其他动作 // - 触发器会被缓存 // - 等其他动作结束后才触发 // - 导致延迟响应或意外触发示例：
玩家输入：跳跃 → 攻击 ↓ ↓ 实际执行：跳跃 → 着陆 → 攻击（延迟触发） ↑ 不想要的攻击！2. 缺乏IDE功能#Mecanim参数：
❌ 无法重命名（需手动查找所有引用） ❌ 无法查找引用 ❌ 无法跨文件对比 ❌ 无代码补全 // 拼写错误，运行时才发现 _animator.SetFloat(&#34;Spead&#34;, 5f); // 应该是&#34;Speed&#34;Animancer脚本变量：
✅ IDE自动重命名 ✅ 查找所有引用 ✅ 代码补全 ✅ 编译时检查 [SerializeField] private float _speed; // IDE支持重命名、查找引用等3. 验证困难#Mecanim：
// 参数是否存在？运行时才知道 _animator.SetFloat(&#34;NonExistentParam&#34;, 5f); // ❌ 无警告，无错误，静默失败Animancer：
[SerializeField] private AnimationClip _clip; // 如果未赋值，Inspector会显示警告 // 编译器也会在某些情况下警告对比示例#武器切换系统#Mecanim方式 - 集中但僵化：
// 所有武器动画必须在单个Controller中 // Animator Controller: // - Sword Layer // - SwordIdle, SwordAttack1, SwordAttack2 // - Bow Layer // - BowIdle, BowDraw, BowShoot // - Staff Layer // - StaffIdle, StaffCast1, StaffCast2 // 脚本中： _animator.SetInteger(&#34;WeaponType&#34;, (int)WeaponType.Sword); _animator.SetTrigger(&#34;Attack&#34;);Animancer方式 - 分离且灵活：
// 每个武器独立管理自己的动画 public class SwordController : MonoBehaviour { [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip[] _attacks; void Attack(int index) { _animancer.Play(_attacks[index]); } } public class BowController : MonoBehaviour { [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip _draw; [SerializeField] private AnimationClip _shoot; void Shoot() { _animancer.Play(_shoot); } }最佳实践#✅ 灵活组织动画#// 方式1：单一职责 public class IdleAnimations : MonoBehaviour { [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip _idleVariation1; [SerializeField] private AnimationClip _idleVariation2; } // 方式2：功能分组 public class CharacterAnimations : MonoBehaviour { [SerializeField] private MovementAnims _movement; [SerializeField] private CombatAnims _combat; [SerializeField] private EmoteAnims _emotes; } // 方式3：状态分组 public class AIAnimations : MonoBehaviour { [SerializeField] private AnimationClip _patrol; [SerializeField] private AnimationClip _chase; [SerializeField] private AnimationClip _attack; [SerializeField] private AnimationClip _retreat; }参考资料#📚 相关文档#animancer-why animancer-clarity animancer-safety 文档版本: 1.0 最后更新: 2025-12-25

Animancer - Comparison 对比总览#📋 目录#概述 四大对比主题 参考资料 概述#本系列文档通过实战场景对比Mecanim和Animancer的实现方式，展示两者在实际开发中的差异。
四大对比主题#1. Playing（播放动画）#&ldquo;How to play a single animation (with or without scripting).&rdquo;
对比内容：
无脚本播放方式 脚本控制播放 理解与维护 复用性 核心差异：
// Mecanim: 需要Controller配置 _animator.Play(&#34;Walk&#34;); // Animancer: 直接播放 _animancer.Play(_walk);📖 animancer-playing
2. Waiting（等待动画）#&ldquo;How to wait until an animation ends before running some code.&rdquo;
对比内容：
状态信息检查 NormalizedTime监控 StateMachineBehaviour End Events Coroutines 核心差异：
// Mecanim: 复杂的状态检查 while (true) { var info = _animator.GetCurrentAnimatorStateInfo(0); if (info.IsName(&#34;Attack&#34;) &amp;&amp; info.normalizedTime &gt;= 1f) break; yield return null; } // Animancer: 简单的事件 var state = _animancer.Play(_attack); state.Events.OnEnd = OnComplete;📖 animancer-waiting
3. Speed and Time（速度和时间）#&ldquo;How to manipulate the speed and time of animations.&rdquo;
对比内容：
固定速度设置 动态速度调整 时间控制 常量时间控制 核心差异：
// Mecanim: 需要参数 _animator.SetFloat(&#34;SpeedMultiplier&#34;, 2f); // Animancer: 直接设置 var state = _animancer.Play(_walk); state.Speed = 2f;📖 animancer-speedandtime
4. Weapon Animations（武器动画）#&ldquo;How to set up a system where each weapon has its own attack animations.&rdquo;
对比内容：
武器系统架构 动画覆盖方式 武器切换实现 内存管理 核心差异：
// Mecanim: AnimatorOverrideController var overrideController = new AnimatorOverrideController(baseController); overrideController[&#34;PlaceholderAttack&#34;] = swordAttack; _animator.runtimeAnimatorController = overrideController; // Animancer: 直接播放 _animancer.Play(weapon.AttackClip);📖 animancer-weaponanimations
对比总结表#场景 Mecanim复杂度 Animancer复杂度 优势方 播放动画 高（需要Controller配置） 低（1行代码） Animancer 等待结束 中（状态检查或Behaviour） 低（End Events） Animancer 速度控制 中（需要参数） 低（直接设置） Animancer 武器系统 高（Override Controller） 低（直接播放） Animancer 快速决策#选择Mecanim的情况#✅ 已有大量Controller资产 ✅ 团队不熟悉编程 ✅ 简单固定的动画流程 选择Animancer的情况#✅ 需要灵活的动画控制 ✅ 复杂的游戏逻辑 ✅ 团队有编程能力 ✅ 需要快速迭代 参考资料#📚 详细对比文档#animancer-playing animancer-waiting animancer-speedandtime animancer-weaponanimations 🎯 Why系列#animancer-why animancer-simplicity animancer-reliability ⚡ 性能分析#animancer-performance 文档版本: 1.0 最后更新: 2025-12-25

Animancer - End Events Alternatives 官方文档#📋 目录#概述 方案对比 方案1：协程（Coroutines） 方案2：手动轮询（Manual Polling） 性能对比 代码示例 最佳实践 FAQ常见问题 参考资料 概述#虽然 End Events 通常是最简单且高效的方式，但 Animancer 还提供了两种替代方案来检测动画结束：
协程（Coroutines）：使用 yield return 等待动画完成 手动轮询（Manual Polling）：在 Update 中检查动画状态 方案对比#📊 三种方案对比表#特性 End Events Coroutines Manual Polling 性能 ⭐⭐⭐⭐⭐ ⭐⭐⭐⭐ ⭐⭐⭐ 易用性 ⭐⭐⭐⭐⭐ ⭐⭐⭐⭐ ⭐⭐⭐ GC分配 无 启动协程时 无 代码简洁 ⭐⭐⭐⭐⭐ ⭐⭐⭐⭐ ⭐⭐ 适用场景 通用 顺序逻辑 条件检测 🎯 选择建议#// ✅ 默认使用 End Events state.Events.OnEnd = OnComplete; // ✅ 顺序逻辑使用 Coroutines yield return state; DoSomething(); // ✅ 复杂条件使用 Manual Polling if (state.NormalizedTime &gt;= 1 &amp;&amp; someCondition) { HandleCompletion(); }方案1：协程（Coroutines）#🎯 核心机制#&ldquo;可以在协程中使用 yield return 等待任何 AnimancerState 完成&rdquo;
状态完成的定义： 停止播放 或 超过其结束时间
📝 基础用法#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 协程方案基础示例 /// &lt;/summary&gt; public class CoroutineBasicExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; [SerializeField] private AnimationClip _IdleClip; void Update() { if (Input.GetKeyDown(KeyCode.Mouse0)) { StartCoroutine(AttackSequence()); } } IEnumerator AttackSequence() { // 播放攻击动画 var state = _Animancer.Play(_AttackClip); // 等待动画完成 yield return state; // 动画完成后继续执行 Debug.Log(&#34;攻击完成&#34;); // 播放Idle动画 _Animancer.Play(_IdleClip); } }🔄 等待多个动画#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 等待多个动画示例 /// &lt;/summary&gt; public class WaitMultipleAnimations : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _Attack1; [SerializeField] private AnimationClip _Attack2; [SerializeField] private AnimationClip _Attack3; void Start() { StartCoroutine(ComboSequence()); } IEnumerator ComboSequence() { Debug.Log(&#34;开始连击&#34;); // 第一段攻击 var state1 = _Animancer.Play(_Attack1); yield return state1; Debug.Log(&#34;第一段完成&#34;); // 第二段攻击 var state2 = _Animancer.Play(_Attack2); yield return state2; Debug.Log(&#34;第二段完成&#34;); // 第三段攻击 var state3 = _Animancer.Play(_Attack3); yield return state3; Debug.Log(&#34;第三段完成&#34;); Debug.Log(&#34;连击结束&#34;); } }🎚️ 等待 Layer 或 AnimancerComponent#扩展用途：可以 yield 整个 Layer 或 AnimancerComponent 以等待所有状态完成
using Animancer; using UnityEngine; /// &lt;summary&gt; /// 等待Layer或Component示例 /// &lt;/summary&gt; public class WaitLayerExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; void Start() { StartCoroutine(WaitForAllAnimations()); } IEnumerator WaitForAllAnimations() { // 播放多个动画 _Animancer.Layers[0].Play(_Animation1); _Animancer.Layers[1].Play(_Animation2); _Animancer.Layers[2].Play(_Animation3); // 等待特定Layer的所有动画完成 yield return _Animancer.Layers[0]; Debug.Log(&#34;Layer 0 的动画完成&#34;); // 或等待整个AnimancerComponent的所有动画完成 yield return _Animancer; Debug.Log(&#34;所有动画完成&#34;); } [SerializeField] private AnimationClip _Animation1; [SerializeField] private AnimationClip _Animation2; [SerializeField] private AnimationClip _Animation3; }⚠️ GC 注意事项#重要：yield 状态本身不产生垃圾回收，但启动协程会产生 GC
// ✅ yield状态：无GC yield return state; // ❌ StartCoroutine：有GC（分配协程对象） StartCoroutine(MyCoroutine());📊 协程完整示例#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 协程方案完整示例 /// 演示复杂的动画序列控制 /// &lt;/summary&gt; public class CoroutineCompleteExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [Header(&#34;技能动画&#34;)] [SerializeField] private AnimationClip _CastStart; [SerializeField] private AnimationClip _CastLoop; [SerializeField] private AnimationClip _CastEnd; [SerializeField] private AnimationClip _Idle; [Header(&#34;特效&#34;)] [SerializeField] private ParticleSystem _ChargeEffect; [SerializeField] private ParticleSystem _ReleaseEffect; private bool _isCharging = false; void Update() { if (Input.GetKeyDown(KeyCode.Alpha1)) { StartCoroutine(CastSkill()); } } IEnumerator CastSkill() { Debug.Log(&#34;开始施法&#34;); // 1. 播放施法开始动画 var startState = _Animancer.Play(_CastStart); yield return startState; Debug.Log(&#34;施法准备完成&#34;); // 2. 启动蓄力特效 _ChargeEffect.Play(); // 3. 播放循环蓄力动画 var loopState = _Animancer.Play(_CastLoop); loopState.IsLooping = true; _isCharging = true; // 4. 等待2秒或玩家松开按键 float chargeTime = 0f; while (_isCharging &amp;&amp; chargeTime &lt; 2f) { chargeTime += Time.deltaTime; yield return null; } Debug.Log($&#34;蓄力时间: {chargeTime:F2}秒&#34;); // 5. 停止蓄力特效 _ChargeEffect.Stop(); // 6. 播放释放动画 var endState = _Animancer.Play(_CastEnd); yield return endState; // 7. 触发释放特效 _ReleaseEffect.Play(); Debug.Log(&#34;技能释放完成&#34;); // 8. 返回Idle _Animancer.Play(_Idle); } void OnGUI() { if (_isCharging &amp;&amp; GUI.Button(new Rect(10, 10, 100, 30), &#34;释放技能&#34;)) { _isCharging = false; } } }方案2：手动轮询（Manual Polling）#🎯 核心机制#保存 Play() 返回的状态引用，每帧检查 NormalizedTime 属性。
完成判断： NormalizedTime &gt;= 1 表示动画完成
📝 基础用法#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 手动轮询基础示例 /// &lt;/summary&gt; public class PollingBasicExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; [SerializeField] private AnimationClip _IdleClip; private AnimancerState _currentState; private bool _isAttacking = false; void Update() { if (Input.GetKeyDown(KeyCode.Mouse0) &amp;&amp; !_isAttacking) { StartAttack(); } // 轮询检测动画完成 if (_isAttacking) { CheckAttackCompletion(); } } void StartAttack() { _isAttacking = true; _currentState = _Animancer.Play(_AttackClip); Debug.Log(&#34;开始攻击&#34;); } void CheckAttackCompletion() { // 检查归一化时间 if (_currentState.NormalizedTime &gt;= 1) { OnAttackComplete(); } } void OnAttackComplete() { _isAttacking = false; Debug.Log(&#34;攻击完成&#34;); _Animancer.Play(_IdleClip); } }🛡️ 安全获取状态#使用 TryGet() 或 GetOrCreate() 避免状态未创建的错误：
using Animancer; using UnityEngine; /// &lt;summary&gt; /// 安全状态获取示例 /// &lt;/summary&gt; public class SafeStateAccessExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; void Update() { // 方法1：TryGet（推荐） if (_Animancer.States.TryGet(_AttackClip, out AnimancerState state)) { if (state.NormalizedTime &gt;= 1) { Debug.Log(&#34;攻击完成&#34;); } } // 方法2：GetOrCreate（确保状态存在） var safeState = _Animancer.States.GetOrCreate(_AttackClip); if (safeState.NormalizedTime &gt;= 1) { Debug.Log(&#34;攻击完成&#34;); } // ❌ 错误：直接访问可能抛出异常 // var dangerousState = _Animancer.States[_AttackClip]; // 状态不存在时报错 } }🔍 高级条件检测#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 高级条件检测示例 /// 结合多个条件判断动画完成 /// &lt;/summary&gt; public class AdvancedPollingExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _ChargeClip; private AnimancerState _chargeState; private bool _isCharging = false; private float _chargeStartTime; void Update() { if (Input.GetKeyDown(KeyCode.Space)) { StartCharge(); } if (Input.GetKeyUp(KeyCode.Space)) { StopCharge(); } if (_isCharging) { CheckChargeConditions(); } } void StartCharge() { _isCharging = true; _chargeStartTime = Time.time; _chargeState = _Animancer.Play(_ChargeClip); _chargeState.IsLooping = true; Debug.Log(&#34;开始蓄力&#34;); } void CheckChargeConditions() { float chargeTime = Time.time - _chargeStartTime; // 条件1：动画播放超过50% bool animationCondition = _chargeState.NormalizedTime &gt;= 0.5f; // 条件2：蓄力时间超过1秒 bool timeCondition = chargeTime &gt;= 1f; // 条件3：角色在地面上 bool groundCondition = IsGrounded(); // 组合条件判断 if (animationCondition &amp;&amp; timeCondition &amp;&amp; groundCondition) { Debug.Log(&#34;蓄力完成，可以释放技能&#34;); // 显示UI提示 } // 条件4：强制最大蓄力时间 if (chargeTime &gt;= 3f) { Debug.Log(&#34;达到最大蓄力时间&#34;); AutoRelease(); } } void StopCharge() { if (_isCharging) { _isCharging = false; float chargeTime = Time.time - _chargeStartTime; Debug.Log($&#34;释放技能（蓄力{chargeTime:F2}秒）&#34;); // 执行技能释放逻辑 } } void AutoRelease() { _isCharging = false; Debug.Log(&#34;自动释放技能&#34;); // 执行技能释放逻辑 } bool IsGrounded() { // 实际项目中的地面检测逻辑 return true; } }📊 状态字典优化#优化方式：通过内部字典高效获取状态
// Animancer内部使用字典存储状态 // 查找效率: O(1) // ✅ 高效：直接从字典获取 var state = _Animancer.States.TryGet(_Clip, out var result); // ❌ 低效：遍历所有状态 foreach (var state in _Animancer.States) { if (state.Clip == _Clip) { } }性能对比#📊 性能测试结果#方案 CPU开销 GC分配 代码行数 适用场景 End Events 最低 0 最少 通用推荐 Coroutines 低 StartCoroutine时 少 顺序逻辑 Manual Polling 中 0 较多 复杂条件 🎯 性能优化建议#// ✅ 最佳：End Events（零开销） state.Events.OnEnd = OnComplete; // ✅ 良好：Coroutines（协程复用） private Coroutine _currentCoroutine; void Play() { if (_currentCoroutine != null) StopCoroutine(_currentCoroutine); _currentCoroutine = StartCoroutine(PlaySequence()); } // ⚠️ 注意：Manual Polling（每帧检查） void Update() { // 只在必要时检查 if (_needsCheck &amp;&amp; _state.NormalizedTime &gt;= 1) { OnComplete(); _needsCheck = false; } }代码示例#示例1：三种方案对比#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 三种方案对比示例 /// &lt;/summary&gt; public class ThreeApproachesExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; [SerializeField] private AnimationClip _IdleClip; void Update() { if (Input.GetKeyDown(KeyCode.Alpha1)) { UseEndEvents(); } else if (Input.GetKeyDown(KeyCode.Alpha2)) { StartCoroutine(UseCoroutines()); } else if (Input.GetKeyDown(KeyCode.Alpha3)) { UseManualPolling(); } } // 方法1：End Events（推荐） void UseEndEvents() { Debug.Log(&#34;[End Events] 开始攻击&#34;); var state = _Animancer.Play(_AttackClip); state.Events.OnEnd = () =&gt; { Debug.Log(&#34;[End Events] 攻击完成&#34;); _Animancer.Play(_IdleClip); }; } // 方法2：Coroutines IEnumerator UseCoroutines() { Debug.Log(&#34;[Coroutines] 开始攻击&#34;); var state = _Animancer.Play(_AttackClip); yield return state; Debug.Log(&#34;[Coroutines] 攻击完成&#34;); _Animancer.Play(_IdleClip); } // 方法3：Manual Polling private AnimancerState _pollingState; private bool _isPolling = false; void UseManualPolling() { Debug.Log(&#34;[Manual Polling] 开始攻击&#34;); _pollingState = _Animancer.Play(_AttackClip); _isPolling = true; } void LateUpdate() { if (_isPolling &amp;&amp; _pollingState.NormalizedTime &gt;= 1) { Debug.Log(&#34;[Manual Polling] 攻击完成&#34;); _isPolling = false; _Animancer.Play(_IdleClip); } } }示例2：复杂协程序列#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 复杂协程序列示例 /// &lt;/summary&gt; public class ComplexCoroutineExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; void Start() { StartCoroutine(BossIntroSequence()); } IEnumerator BossIntroSequence() { Debug.Log(&#34;=== BOSS登场序列开始 ===&#34;); // 1. 播放入场动画 yield return _Animancer.Play(_BossEnter); Debug.Log(&#34;BOSS入场完成&#34;); // 2. 等待1秒 yield return new WaitForSeconds(1f); // 3. 播放咆哮动画 yield return _Animancer.Play(_BossRoar); Debug.Log(&#34;BOSS咆哮完成&#34;); // 4. 触发屏幕震动 CameraShake(); // 5. 等待0.5秒 yield return new WaitForSeconds(0.5f); // 6. 播放战斗准备动画 yield return _Animancer.Play(_BossBattleReady); Debug.Log(&#34;BOSS战斗准备完成&#34;); // 7. 进入Idle循环 _Animancer.Play(_BossIdle); Debug.Log(&#34;=== BOSS登场序列结束，战斗开始 ===&#34;); // 8. 启用BOSS AI EnableBossAI(); } void CameraShake() { Debug.Log(&#34;屏幕震动&#34;); } void EnableBossAI() { Debug.Log(&#34;启用BOSS AI&#34;); } [SerializeField] private AnimationClip _BossEnter; [SerializeField] private AnimationClip _BossRoar; [SerializeField] private AnimationClip _BossBattleReady; [SerializeField] private AnimationClip _BossIdle; }最佳实践#✅ DO（推荐做法）#优先使用 End Events // ✅ 默认选择 state.Events.OnEnd = OnComplete;顺序逻辑使用协程 // ✅ 适合多步骤序列 yield return state1; yield return state2; yield return state3;复杂条件使用轮询 // ✅ 适合多条件判断 if (state.NormalizedTime &gt;= 1 &amp;&amp; otherCondition) { HandleCompletion(); }使用 TryGet 安全获取状态 // ✅ 避免异常 if (_Animancer.States.TryGet(_Clip, out var state)) { // 使用state }❌ DON&rsquo;T（避免做法）#不要过度使用协程 // ❌ 简单情况不要用协程 StartCoroutine(PlayAndThenIdle()); // 产生GC不要在轮询中做重复操作 // ❌ 每帧重复执行 void Update() { if (state.NormalizedTime &gt;= 1) { SomeExpensiveOperation(); // 没有标志位！ } }不要直接访问可能不存在的状态 // ❌ 可能抛出异常 var state = _Animancer.States[_Clip];FAQ常见问题#Q1: 什么时候应该使用替代方案？#A:
End Events: 95%的情况 Coroutines: 需要顺序执行多个步骤时 Manual Polling: 需要复杂条件判断时 Q2: 协程的GC开销大吗？#A: 适中：
// GC来源： // 1. StartCoroutine() - 分配协程对象 // 2. yield return new WaitForSeconds() - 分配等待对象 // 优化： // - 缓存WaitForSeconds对象 // - yield return state（无GC）Q3: 如何避免手动轮询的性能问题？#A: 使用标志位：
private bool _needsCheck = false; void Update() { if (_needsCheck) { if (state.NormalizedTime &gt;= 1) { OnComplete(); _needsCheck = false; // 停止检查 } } }Q4: yield return Layer 是什么意思？#A: 等待该Layer的所有动画完成：
// 等待Layer 0的所有动画 yield return _Animancer.Layers[0]; // 等待所有Layer的所有动画 yield return _Animancer;Q5: 三种方案可以混用吗？#A: 可以：
IEnumerator MixedApproach() { // 使用协程等待动画 yield return _Animancer.Play(_Anim1); // 使用End Event处理完成 var state = _Animancer.Play(_Anim2); state.Events.OnEnd = OnComplete; // 使用轮询检查条件 _needsPolling = true; }参考资料#📚 相关文档#Animancer Events - End Events AnimancerState API Unity Coroutines 🔗 API 参考#AnimancerState.NormalizedTime AnimancerState.IsPlaying AnimancerComponent.States.TryGet() AnimancerComponent.States.GetOrCreate() 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer - Simplicity 简洁性#📋 目录#核心原则 复杂度对比 控制灵活性 参考资料 核心原则#动画系统应该只需要两个输入：要动画的对象 + 要播放的动画
理想方案#thing.Play(animation);复杂度对比#Mecanim方式：7个步骤#1. 获取Animator组件 ↓ 2. 创建Animator Controller资产 ↓ 3. 分配到Controller字段 ↓ 4. 创建状态 ↓ 5. 给状态命名 ↓ 6. 分配动画片段 ↓ 7. 调用Play方法代码：
_animator.Play(&#34;StateName&#34;); // 需要7步准备工作Animancer方式：1个步骤#[SerializeField] private AnimancerComponent _animancer; [SerializeField] private AnimationClip _clip; _animancer.Play(_clip); // 仅此而已控制灵活性#Mecanim的限制#功能 Mecanim Animancer 即时播放 ❌ 需要预配置 ✅ 直接播放 运行时修改过渡 ❌ 不可能 ✅ 随时修改 动态速度调整 ⚠️ 需要参数 ✅ 直接设置 运行时Layer Mask ❌ 不支持 ✅ 支持 Inspector手动播放 ❌ 不支持 ✅ 支持 代码示例#运行时修改过渡时间：
// Mecanim - 不可能 // Controller中的过渡时间是固定的 // Animancer - 简单 _animancer.Play(_clip, fadeDuration: 0.5f); // 随时修改动态速度调整：
// Mecanim - 需要参数 // 1. 创建Float参数 &#34;SpeedMultiplier&#34; // 2. 在状态中设置Parameter _animator.SetFloat(&#34;SpeedMultiplier&#34;, 2f); // Animancer - 直接设置 var state = _animancer.Play(_clip); state.Speed = 2f;运行时修改Layer Mask：
// Mecanim - 不支持 // Layer Mask必须在Controller中预先配置 // Animancer - 支持 var layer = _animancer.Layers[1]; layer.SetMask(_upperBodyMask); // 运行时修改规模化问题#Mecanim Controller 的混乱#&ldquo;随着复杂度增加，Controller会变成无法组织的混乱网络&rdquo;
简单Controller (5个状态) ↓ 中等Controller (20个状态) ↓ 复杂Controller (50+个状态) ↓ ❌ 混乱的意大利面网络Unity官方示例的问题： 即使是Unity官方博客中的示例，也会随着复杂度增加而&quot;变成无法轻松组织的混乱网络&quot;。
Animancer 的可扩展性#// 小型系统 public class SimpleCharacter : MonoBehaviour { [SerializeField] private AnimationClip _idle; [SerializeField] private AnimationClip _walk; } // 大型系统 - 模块化组织 public class ComplexCharacter : MonoBehaviour { [SerializeField] private MovementAnimations _movement; [SerializeField] private CombatAnimations _combat; [SerializeField] private InteractionAnimations _interactions; } [System.Serializable] public class MovementAnimations { public AnimationClip Idle; public AnimationClip Walk; public AnimationClip Run; public AnimationClip Jump; }实战对比#场景：播放攻击动画#Mecanim：
打开Animator Controller 创建&quot;Attack&quot;状态 分配动画片段 创建Bool参数&quot;IsAttacking&quot; 创建Idle→Attack过渡 设置过渡条件：IsAttacking == true 创建Attack→Idle过渡 设置Exit Time // 代码中 _animator.SetBool(&#34;IsAttacking&#34;, true); // 需要在某处重置为falseAnimancer：
void Attack() { var state = _animancer.Play(_attackClip); state.Events.OnEnd = () =&gt; _animancer.Play(_idleClip); }最佳实践#✅ Animancer的简洁优势#// 1. 无需预配置 _animancer.Play(_newClip); // 立即播放任何Clip // 2. 灵活的淡入时间 _animancer.Play(_clip, 0.1f); // 快速切换 _animancer.Play(_clip, 0.5f); // 平滑切换 // 3. 动态控制 var state = _animancer.Play(_clip); state.Speed = 2f; // 速度 state.Time = 0.5f; // 时间 state.Weight = 0.8f; // 权重 state.IsLooping = false; // 循环 // 4. 即时事件 state.Events.OnEnd = OnComplete; state.Events.AddNormalized(0.5f, OnHalfway);参考资料#📚 相关文档#animancer-why animancer-transparency animancer-adaptability 文档版本: 1.0 最后更新: 2025-12-25

