Animancer - Strings 官方文档#📋 目录#概述 StringReference StringAsset 代码示例 最佳实践 参考资料 概述#Strings 系统提供了两个工具来优化字符串处理性能：
StringReference - 缓存字符串引用以避免重复的字符串比较 StringAsset - 将字符串封装为 ScriptableObject 资产 🎯 核心优势#工具 用途 性能优化 StringReference 缓存字符串引用 避免重复的字符串比较 StringAsset 字符串资产化 引用比较替代值比较 StringReference#问题：重复的字符串查找#// ❌ 每次调用都进行字符串比较 public void UpdateParameter() { _animancer.Parameters.Get&lt;float&gt;(&#34;Speed&#34;); // 字符串比较 _animancer.Parameters.Get&lt;float&gt;(&#34;Speed&#34;); // 再次比较 _animancer.Parameters.Get&lt;float&gt;(&#34;Speed&#34;); // 又一次比较 }解决方案：StringReference#using Animancer; public class CharacterController : MonoBehaviour { // ✅ 缓存 StringReference private static readonly StringReference SpeedParameter = &#34;Speed&#34;; private AnimancerComponent _animancer; void Update() { // 使用缓存的引用（更快） var speed = _animancer.Parameters.Get&lt;float&gt;(SpeedParameter); } }工作原理#/// &lt;summary&gt; /// StringReference 内部结构 /// &lt;/summary&gt; public readonly struct StringReference { private readonly string _string; private readonly int _hashCode; public StringReference(string value) { _string = value; _hashCode = value?.GetHashCode() ?? 0; } // 隐式转换 public static implicit operator StringReference(string value) =&gt; new StringReference(value); }性能对比#using UnityEngine; public class StringPerformanceTest : MonoBehaviour { private ParameterDictionary _parameters; private static readonly StringReference CachedKey = &#34;TestParam&#34;; void TestPerformance() { // ❌ 方式1：原始字符串（较慢） for (int i = 0; i &lt; 10000; i++) { _parameters.Get&lt;float&gt;(&#34;TestParam&#34;); } // ✅ 方式2：StringReference（更快） for (int i = 0; i &lt; 10000; i++) { _parameters.Get&lt;float&gt;(CachedKey); } } }StringAsset#概念#StringAsset 是一个 ScriptableObject 包装器，将字符串作为项目资产。
using Animancer; using UnityEngine; /// &lt;summary&gt; /// 字符串资产 /// &lt;/summary&gt; [CreateAssetMenu(menuName = &#34;Animancer/String Asset&#34;)] public class StringAsset : ScriptableObject { [SerializeField] private string _value; public string Value =&gt; _value; // 隐式转换为 string public static implicit operator string(StringAsset asset) =&gt; asset._value; // 隐式转换为 StringReference public static implicit operator StringReference(StringAsset asset) =&gt; new StringReference(asset._value); }使用场景#场景1：共享参数名称#using Animancer; using UnityEngine; public class SharedParameterExample : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; // 在 Inspector 中分配 StringAsset [SerializeField] private StringAsset _speedParameter; [SerializeField] private StringAsset _jumpParameter; void Update() { // 使用 StringAsset var speed = _animancer.Parameters.Get&lt;float&gt;(_speedParameter); var canJump = _animancer.Parameters.Get&lt;bool&gt;(_jumpParameter); Debug.Log($&#34;Speed: {speed}, CanJump: {canJump}&#34;); } }场景2：多个系统共享常量#using UnityEngine; /// &lt;summary&gt; /// 创建共享的字符串常量资产 /// &lt;/summary&gt; public class AnimationParameters : ScriptableObject { public static StringAsset Speed; public static StringAsset IsGrounded; public static StringAsset AttackTrigger; [RuntimeInitializeOnLoadMethod] static void Initialize() { // 加载资产 Speed = Resources.Load&lt;StringAsset&gt;(&#34;Parameters/Speed&#34;); IsGrounded = Resources.Load&lt;StringAsset&gt;(&#34;Parameters/IsGrounded&#34;); AttackTrigger = Resources.Load&lt;StringAsset&gt;(&#34;Parameters/AttackTrigger&#34;); } } // 在多个脚本中使用 public class PlayerController : MonoBehaviour { void Update() { _animancer.Parameters.Set(AnimationParameters.Speed, currentSpeed); } } public class CombatSystem : MonoBehaviour { void Attack() { _animancer.Parameters.Set(AnimationParameters.AttackTrigger, true); } }代码示例#示例1：完整的 StringReference 使用#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 使用 StringReference 优化参数访问 /// &lt;/summary&gt; public class OptimizedParameterAccess : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; // ✅ 静态缓存所有参数名称 private static readonly StringReference Speed = &#34;Speed&#34;; private static readonly StringReference TurnRate = &#34;TurnRate&#34;; private static readonly StringReference IsGrounded = &#34;IsGrounded&#34;; private static readonly StringReference IsAirborne = &#34;IsAirborne&#34;; void Update() { // 高效的参数访问 float speed = GetMovementSpeed(); _animancer.Parameters.Set(Speed, speed); float turnRate = CalculateTurnRate(); _animancer.Parameters.Set(TurnRate, turnRate); bool grounded = CheckGrounded(); _animancer.Parameters.Set(IsGrounded, grounded); _animancer.Parameters.Set(IsAirborne, !grounded); } float GetMovementSpeed() =&gt; 5f; float CalculateTurnRate() =&gt; 180f; bool CheckGrounded() =&gt; true; }示例2：StringAsset 配置系统#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 使用 StringAsset 创建可配置的参数系统 /// &lt;/summary&gt; public class ConfigurableParameterSystem : MonoBehaviour { [System.Serializable] public class ParameterConfig { public StringAsset ParameterName; public float DefaultValue; public float MinValue; public float MaxValue; } [SerializeField] private AnimancerComponent _animancer; [SerializeField] private ParameterConfig[] _parameters; void Start() { // 初始化所有参数 foreach (var config in _parameters) { _animancer.Parameters.Set( config.ParameterName, config.DefaultValue ); } } public void SetParameter(StringAsset paramName, float value) { // 查找配置 var config = System.Array.Find( _parameters, p =&gt; p.ParameterName == paramName ); if (config != null) { // 应用范围限制 value = Mathf.Clamp(value, config.MinValue, config.MaxValue); _animancer.Parameters.Set(paramName, value); } } }示例3：参数名称中心化管理#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 中心化管理所有动画参数 /// &lt;/summary&gt; public static class AnimParams { // 移动参数 public static readonly StringReference Speed = &#34;Speed&#34;; public static readonly StringReference Direction = &#34;Direction&#34;; public static readonly StringReference TurnRate = &#34;TurnRate&#34;; // 状态参数 public static readonly StringReference IsGrounded = &#34;IsGrounded&#34;; public static readonly StringReference IsAirborne = &#34;IsAirborne&#34;; public static readonly StringReference IsCrouching = &#34;IsCrouching&#34;; // 战斗参数 public static readonly StringReference AttackSpeed = &#34;AttackSpeed&#34;; public static readonly StringReference WeaponType = &#34;WeaponType&#34;; public static readonly StringReference IsBlocking = &#34;IsBlocking&#34;; } /// &lt;summary&gt; /// 使用中心化参数 /// &lt;/summary&gt; public class CentralizedParameterUsage : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; void Update() { // ✅ 使用中心化的参数名称 _animancer.Parameters.Set(AnimParams.Speed, 5f); _animancer.Parameters.Set(AnimParams.IsGrounded, true); // 类型安全且易于重构 } }示例4：创建 StringAsset 资产#using Animancer; using UnityEngine; #if UNITY_EDITOR using UnityEditor; /// &lt;summary&gt; /// 编辑器工具：批量创建 StringAsset /// &lt;/summary&gt; public static class StringAssetCreator { [MenuItem(&#34;Assets/Create/Animancer/Batch Create String Assets&#34;)] static void CreateStringAssets() { string[] parameterNames = new[] { &#34;Speed&#34;, &#34;Direction&#34;, &#34;IsGrounded&#34;, &#34;AttackSpeed&#34; }; foreach (var paramName in parameterNames) { // 创建 StringAsset 实例 var asset = ScriptableObject.CreateInstance&lt;StringAsset&gt;(); // 设置值（需要反射或公开setter） var serializedObject = new SerializedObject(asset); serializedObject.FindProperty(&#34;_value&#34;).stringValue = paramName; serializedObject.ApplyModifiedProperties(); // 保存资产 string path = $&#34;Assets/Parameters/{paramName}.asset&#34;; AssetDatabase.CreateAsset(asset, path); } AssetDatabase.SaveAssets(); Debug.Log($&#34;创建了 {parameterNames.Length} 个 StringAsset&#34;); } } #endif最佳实践#✅ DO（推荐做法）#1. 使用 static readonly 缓存 StringReference#// ✅ 好：静态缓存 public class Controller : MonoBehaviour { private static readonly StringReference SpeedParam = &#34;Speed&#34;; void Update() { _animancer.Parameters.Set(SpeedParam, 5f); } }2. 中心化管理参数名称#// ✅ 好：统一管理 public static class AnimParams { public static readonly StringReference Speed = &#34;Speed&#34;; public static readonly StringReference Jump = &#34;Jump&#34;; }3. 使用 StringAsset 共享配置#// ✅ 好：在多个脚本间共享 [SerializeField] private StringAsset _speedParameter;❌ DON&rsquo;T（避免做法）#1. 重复使用原始字符串#// ❌ 差：每次都创建新字符串 void Update() { _animancer.Parameters.Set(&#34;Speed&#34;, 5f); _animancer.Parameters.Get&lt;float&gt;(&#34;Speed&#34;); _animancer.Parameters.Get&lt;float&gt;(&#34;Speed&#34;); // 重复比较 }2. 在非静态字段中缓存#// ❌ 差：实例字段浪费内存 public class Controller : MonoBehaviour { private StringReference _speedParam = &#34;Speed&#34;; // 每个实例都有副本 }3. 硬编码字符串散落各处#// ❌ 差：难以维护 void Update() { _animancer.Parameters.Set(&#34;Speed&#34;, 5f); } void FixedUpdate() { _animancer.Parameters.Set(&#34;Spead&#34;, 3f); // 拼写错误！ }FAQ#Q1: StringReference 和 string 有什么区别？#A: StringReference 缓存了字符串的哈希码，避免重复的字符串比较操作。
// 原始字符串：每次都比较字符内容 _parameters.Get&lt;float&gt;(&#34;Speed&#34;); // O(n) // StringReference：使用缓存的哈希码 _parameters.Get&lt;float&gt;(SpeedRef); // O(1)Q2: 什么时候使用 StringAsset？#A: 当需要在多个脚本或预制体间共享相同的参数名称时。
// 场景1：多个系统使用相同参数 [SerializeField] private StringAsset _speedParam; // 在Inspector中分配 // 场景2：避免拼写错误 // StringAsset 提供资产引用，避免硬编码字符串Q3: 如何在Inspector中编辑 StringAsset？#A: 创建自定义编辑器或直接在 StringAsset 中公开字段：
[CreateAssetMenu] public class StringAsset : ScriptableObject { [SerializeField] private string _value; // 在Inspector中可编辑 public string Value =&gt; _value; }Q4: 性能提升有多大？#A: 取决于调用频率：
低频调用（每秒几次）：差异可忽略 高频调用（每帧多次）：可提升 10-30% 极高频调用（每帧数百次）：可提升 50%+ Q5: 可以在运行时创建 StringReference 吗？#A: 可以，但推荐静态缓存：
// ✅ 推荐：编译时创建 private static readonly StringReference Speed = &#34;Speed&#34;; // ⚠️ 可行但不推荐：运行时创建 void Start() { StringReference speedRef = &#34;Speed&#34;; // 每次Start都创建 }参考资料#📚 相关文档#Parameters Animancer API 💡 相关类型#StringReference - 字符串引用结构体 StringAsset - 字符串资产 ScriptableObject ParameterDictionary - 参数字典 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer - Timeline 官方文档#📋 目录#概述 PlayableAssetTransition PlayableAssetState 代码示例 重要限制 最佳实践 参考资料 概述#Timeline 集成允许 Animancer 播放 Unity Timeline 资产作为动画状态。
⚠️ 授权要求：此功能仅限 Pro 版本
🎯 典型应用场景#过场动画（Cutscene） 复杂的多轨道动画序列 带特效、音频、相机的动画 核心类型#类型 说明 PlayableAssetTransition Timeline 转换配置 PlayableAssetState Timeline 播放状态 PlayableAssetTransition#基本用法#using Animancer; using UnityEngine; using UnityEngine.Playables; public class TimelineExample : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _cutsceneTimeline; void Start() { // 创建 Timeline 转换 var transition = new PlayableAssetTransition { Asset = _cutsceneTimeline, FadeDuration = 0.25f }; // 播放 Timeline _animancer.Play(transition); } }Transition 配置#using Animancer; using UnityEngine; using UnityEngine.Playables; public class TimelineTransitionConfig : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _timeline; void PlayTimeline() { var transition = new PlayableAssetTransition { // Timeline 资产 Asset = _timeline, // 淡入时间 FadeDuration = 0.5f, // 播放速度 Speed = 1f, // 是否循环 IsLooping = false, // 起始时间（秒） NormalizedStartTime = 0f }; var state = _animancer.Play(transition); // 添加结束事件 state.Events.OnEnd = OnTimelineEnd; } void OnTimelineEnd() { Debug.Log(&#34;Timeline 播放完成&#34;); } }PlayableAssetState#状态访问#using Animancer; using UnityEngine; using UnityEngine.Playables; public class TimelineStateAccess : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _timeline; private PlayableAssetState _timelineState; void Start() { // 播放并获取状态 _timelineState = _animancer.Play(_timeline) as PlayableAssetState; if (_timelineState != null) { Debug.Log($&#34;Timeline 长度: {_timelineState.Length}秒&#34;); Debug.Log($&#34;当前时间: {_timelineState.Time}秒&#34;); } } void Update() { if (_timelineState != null) { // 查询播放进度 float progress = _timelineState.NormalizedTime; Debug.Log($&#34;播放进度: {progress * 100}%&#34;); } } }播放控制#using Animancer; using UnityEngine; using UnityEngine.Playables; public class TimelineControl : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _timeline; private PlayableAssetState _state; void Start() { _state = _animancer.Play(_timeline) as PlayableAssetState; } void Update() { if (_state == null) return; // 暂停/继续 if (Input.GetKeyDown(KeyCode.Space)) { _state.IsPlaying = !_state.IsPlaying; } // 调整速度 if (Input.GetKeyDown(KeyCode.Alpha1)) _state.Speed = 0.5f; // 慢速 if (Input.GetKeyDown(KeyCode.Alpha2)) _state.Speed = 1f; // 正常 if (Input.GetKeyDown(KeyCode.Alpha3)) _state.Speed = 2f; // 快速 // 跳转到指定时间 if (Input.GetKeyDown(KeyCode.R)) _state.Time = 0; // 重置到开始 } }代码示例#示例1：过场动画系统#using Animancer; using UnityEngine; using UnityEngine.Playables; using System; /// &lt;summary&gt; /// 过场动画播放器 /// &lt;/summary&gt; public class CutscenePlayer : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset[] _cutscenes; private PlayableAssetState _currentCutscene; private int _currentIndex = 0; public event Action OnCutsceneComplete; public event Action OnAllCutscenesComplete; public void PlayCutscene(int index) { if (index &lt; 0 || index &gt;= _cutscenes.Length) { Debug.LogError($&#34;过场动画索引 {index} 超出范围&#34;); return; } _currentIndex = index; var timeline = _cutscenes[index]; // 播放 Timeline var transition = new PlayableAssetTransition { Asset = timeline, FadeDuration = 0.5f }; _currentCutscene = _animancer.Play(transition) as PlayableAssetState; // 添加完成回调 if (_currentCutscene != null) { _currentCutscene.Events.OnEnd = OnCutsceneEnd; } Debug.Log($&#34;播放过场动画 {index}: {timeline.name}&#34;); } public void PlayNext() { if (_currentIndex + 1 &lt; _cutscenes.Length) { PlayCutscene(_currentIndex + 1); } else { Debug.Log(&#34;所有过场动画已播放完毕&#34;); OnAllCutscenesComplete?.Invoke(); } } public void Skip() { if (_currentCutscene != null) { _currentCutscene.Time = _currentCutscene.Length; } } public void Pause() { if (_currentCutscene != null) { _currentCutscene.IsPlaying = false; } } public void Resume() { if (_currentCutscene != null) { _currentCutscene.IsPlaying = true; } } void OnCutsceneEnd() { Debug.Log($&#34;过场动画 {_currentIndex} 播放完成&#34;); OnCutsceneComplete?.Invoke(); } void Update() { // 按 Esc 跳过 if (Input.GetKeyDown(KeyCode.Escape)) { Skip(); } // 按 Space 暂停/继续 if (Input.GetKeyDown(KeyCode.Space)) { if (_currentCutscene != null) { _currentCutscene.IsPlaying = !_currentCutscene.IsPlaying; } } } }示例2：Timeline 序列播放器#using Animancer; using UnityEngine; using UnityEngine.Playables; using System.Collections.Generic; /// &lt;summary&gt; /// Timeline 序列播放器 /// 按顺序播放多个 Timeline /// &lt;/summary&gt; public class TimelineSequence : MonoBehaviour { [System.Serializable] public class TimelineEntry { public PlayableAsset Timeline; public float FadeDuration = 0.25f; public bool WaitForCompletion = true; } [SerializeField] private AnimancerComponent _animancer; [SerializeField] private List&lt;TimelineEntry&gt; _sequence; private int _currentIndex = 0; private PlayableAssetState _currentState; void Start() { PlaySequence(); } public void PlaySequence() { _currentIndex = 0; PlayCurrent(); } void PlayCurrent() { if (_currentIndex &gt;= _sequence.Count) { Debug.Log(&#34;序列播放完成&#34;); return; } var entry = _sequence[_currentIndex]; var transition = new PlayableAssetTransition { Asset = entry.Timeline, FadeDuration = entry.FadeDuration }; _currentState = _animancer.Play(transition) as PlayableAssetState; if (_currentState != null &amp;&amp; entry.WaitForCompletion) { _currentState.Events.OnEnd = PlayNext; } else { // 立即播放下一个 PlayNext(); } Debug.Log($&#34;播放 Timeline {_currentIndex}: {entry.Timeline.name}&#34;); } void PlayNext() { _currentIndex++; PlayCurrent(); } }示例3：Timeline 与动画混合#using Animancer; using UnityEngine; using UnityEngine.Playables; /// &lt;summary&gt; /// Timeline 与普通动画的混合 /// &lt;/summary&gt; public class TimelineBlending : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _cutsceneTimeline; [SerializeField] private AnimationClip _idleClip; [SerializeField] private AnimationClip _walkClip; void Start() { // 初始播放 Idle _animancer.Play(_idleClip); } public void PlayCutscene() { // 从 Idle/Walk 淡入到 Timeline var transition = new PlayableAssetTransition { Asset = _cutsceneTimeline, FadeDuration = 0.5f // 平滑过渡 }; var state = _animancer.Play(transition); // Timeline 结束后返回 Idle state.Events.OnEnd = () =&gt; { _animancer.Play(_idleClip, 0.5f); }; } public void StopCutscene() { // 随时可以打断 Timeline 返回游戏动画 _animancer.Play(_walkClip, 0.25f); } }示例4：Timeline 事件监听#using Animancer; using UnityEngine; using UnityEngine.Playables; using UnityEngine.Timeline; /// &lt;summary&gt; /// 监听 Timeline 中的事件 /// &lt;/summary&gt; public class TimelineEventListener : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private PlayableAsset _timeline; void Start() { PlayTimelineWithEvents(); } void PlayTimelineWithEvents() { var state = _animancer.Play(_timeline) as PlayableAssetState; if (state != null) { // 在25%进度触发事件 state.Events.AddNormalized(0.25f, () =&gt; { Debug.Log(&#34;Timeline 播放到 25%&#34;); }); // 在50%进度触发事件 state.Events.AddNormalized(0.5f, () =&gt; { Debug.Log(&#34;Timeline 播放到 50%&#34;); }); // 在75%进度触发事件 state.Events.AddNormalized(0.75f, () =&gt; { Debug.Log(&#34;Timeline 播放到 75%&#34;); }); // 结束事件 state.Events.OnEnd = () =&gt; { Debug.Log(&#34;Timeline 播放完成&#34;); }; } } }重要限制#⚠️ 限制1：不支持多个 Animator#Timeline 默认控制场景中的所有 Animator，但 Animancer 只能控制一个。
// ❌ 问题：Timeline 有多个 Animation Track 绑定不同角色 // Timeline: // - Track 1 → Character A (Animator) // - Track 2 → Character B (Animator) // - Track 3 → Character C (Animator) // Animancer 只能控制一个 Animator（通常是主角） _animancer.Play(_timeline); // 只有主角会播放动画解决方案：为每个角色创建单独的 Timeline
// ✅ 每个角色自己的 Timeline [SerializeField] private PlayableAsset _characterATimeline; [SerializeField] private PlayableAsset _characterBTimeline; _characterA.Animancer.Play(_characterATimeline); _characterB.Animancer.Play(_characterBTimeline);⚠️ 限制2：无法在 Timeline 中引用 Animancer 状态#// ❌ 不支持：在 Timeline Track 中直接引用 Animancer 状态 // Timeline 使用 Animation Clip，不能直接使用 Animancer Transition解决方案：使用原始 AnimationClip
// ✅ 在 Timeline 中使用 AnimationClip // Timeline Animation Track → 拖入 .anim 文件⚠️ 限制3：Timeline 内的事件优先级高#// ⚠️ 注意：Timeline 自带的 Signal 和 Marker 优先级更高 // 如果 Timeline 中已有事件，Animancer Events 可能不会触发最佳实践#✅ DO（推荐做法）#1. 为过场动画使用 Timeline#// ✅ 好：复杂过场动画用 Timeline var cutscene = new PlayableAssetTransition { Asset = _cinematicTimeline, FadeDuration = 1f }; _animancer.Play(cutscene);2. 缓存 PlayableAssetState#// ✅ 好：缓存状态以便控制 private PlayableAssetState _cutsceneState; void PlayCutscene() { _cutsceneState = _animancer.Play(_timeline) as PlayableAssetState; } void Skip() { if (_cutsceneState != null) _cutsceneState.Time = _cutsceneState.Length; }3. 添加结束回调#// ✅ 好：处理 Timeline 结束 state.Events.OnEnd = () =&gt; { // 返回游戏状态 _animancer.Play(_idleClip); };❌ DON&rsquo;T（避免做法）#1. 在游戏循环中使用 Timeline#// ❌ 差：Timeline 不适合游戏循环动画 _animancer.Play(_walkTimeline); // 用 AnimationClip 代替2. 过度依赖 Timeline#// ❌ 差：简单动画不需要 Timeline var simpleAnim = new PlayableAssetTransition { Asset = _oneClipTimeline // 直接用 AnimationClip }; // ✅ 好 _animancer.Play(_animClip);3. 忘记释放资源#// ❌ 差：不清理 _animancer.Play(_timeline); // ✅ 好：播放完毕后停止 state.Events.OnEnd = () =&gt; { _animancer.Stop(state); };FAQ#Q1: Timeline 和 AnimationClip 有什么区别？#A:
特性 AnimationClip Timeline 用途 单个动画 多轨道序列 复杂度 简单 复杂 性能 轻量 较重 适用场景 游戏循环动画 过场动画 Q2: 如何在 Timeline 中控制多个角色？#A: 为每个角色创建独立的 Timeline 或使用 PlayableDirector：
// 方案1：每个角色单独的 Timeline _characterA.Animancer.Play(_timelineA); _characterB.Animancer.Play(_timelineB); // 方案2：使用 Unity 的 PlayableDirector GetComponent&lt;PlayableDirector&gt;().Play(_multiCharTimeline);Q3: Timeline 播放期间可以切换到其他动画吗？#A: 可以，使用 Play() 打断：
// 播放 Timeline var state = _animancer.Play(_timeline); // 随时可以打断 if (Input.GetKeyDown(KeyCode.Escape)) { _animancer.Play(_idleClip, 0.25f); // 打断并淡入 Idle }Q4: 如何循环播放 Timeline？#A: 设置 IsLooping：
var transition = new PlayableAssetTransition { Asset = _timeline, IsLooping = true // 循环播放 }; _animancer.Play(transition);Q5: Timeline 性能如何？#A: Timeline 比普通 AnimationClip 开销更大：
AnimationClip: ~0.1ms Timeline (1 track): ~0.3ms Timeline (多 track): ~1ms+ 因此，仅在需要多轨道功能时使用 Timeline。
