Animancer - Transparency 透明性#📋 目录#核心理念 Mecanim的问题 Animancer的解决 代码对比 参考资料 核心理念#&ldquo;追逐两只兔子，一只都抓不到&rdquo; - 孔子
Mecanim试图同时做两件事：
动画系统 有限状态机 Animancer专注于做好一件事：动画管理
Mecanim的问题#1. 混合职责#Animator Controller = 动画系统 + FSM ↓ 都做得不够好动画系统的问题：
内部逻辑不可见 无法调试 延迟执行 FSM的问题：
强制使用特定的逻辑定义方式 无法自由修改 无法访问源代码 2. 黑盒系统#// Mecanim - 无法知道内部发生了什么 _animator.Play(&#34;Walk&#34;); // 🤔 它真的播放了吗？ // 🤔 什么时候开始播放？ // 🤔 为什么没有播放？ // ❌ 无法调试3. 延迟反馈#// 调用Play _animator.Play(&#34;Jump&#34;); // 立即检查状态 var info = _animator.GetCurrentAnimatorStateInfo(0); if (info.IsName(&#34;Jump&#34;)) { // ❌ 永远不会进入这里！ // 因为状态还没更新 }Animancer的解决#1. 职责分离#Animancer = 纯动画系统 FSM系统 = 独立的状态机（可选） ↓ 各司其职，都做得很好2. 完全透明#// Animancer - 完全可见 var state = _animancer.Play(_walk); // ✅ 立即获取所有信息 Debug.Log($&#34;Is Playing: {state.IsPlaying}&#34;); Debug.Log($&#34;Length: {state.Length}&#34;); Debug.Log($&#34;Time: {state.Time}&#34;); Debug.Log($&#34;Weight: {state.Weight}&#34;); Debug.Log($&#34;Speed: {state.Speed}&#34;);3. 源代码访问#Pro版本：
✅ 包含完整Animancer源代码 ✅ 可以调试内部实现 ✅ 可以修改和扩展 Lite版本：
✅ FSM系统源代码包含 ✅ 可以自由修改FSM 代码对比#状态切换#Mecanim - 延迟执行，无反馈：
// 调用方法 _animator.Play(&#34;State Name&#34;); // ❌ 无返回值 // ❌ 不知道是否成功 // ❌ 需要等待下一帧才能确认Animancer - 即时执行，有反馈：
// FSM方式 bool success = _stateMachine.TrySetState(state); if (success) { Debug.Log(&#34;成功切换状态&#34;); } else { Debug.Log(&#34;无法切换状态&#34;); // 可以检查原因： if (!state.CanEnterState) Debug.Log(&#34;CanEnterState返回false&#34;); }调试动画#Mecanim - 黑盒：
// 播放动画 _animator.Play(&#34;Attack&#34;); // ❓ 无法知道： // - 为什么没播放？ // - 过渡参数是什么？ // - 当前权重是多少？ // - 混合了哪些动画？Animancer - 透明：
// 播放动画 var state = _animancer.Play(_attack); // ✅ 可以检查所有细节 Debug.Log($&#34;Current State: {_animancer.States.Current}&#34;); Debug.Log($&#34;Previous State: {_animancer.States.Previous}&#34;); Debug.Log($&#34;Layer Count: {_animancer.Layers.Count}&#34;); // ✅ 可以遍历所有状态 foreach (var s in _animancer.States) { Debug.Log($&#34;State: {s.Key}, Weight: {s.Weight}&#34;); }FSM实现#Mecanim - 固定实现：
// ❌ 无法修改FSM行为 // ❌ 必须使用Animator Controller的方式 // ❌ 无法访问源代码Animancer - 开源FSM：
// ✅ 完整的FSM源代码 // ✅ 可以自由修改 // ✅ 可以扩展功能 public class MyCustomState : StateBehaviour { // 可以添加自定义逻辑 public override void OnEnterState() { base.OnEnterState(); // 自定义进入逻辑 } public override bool CanEnterState { get { // 自定义条件检查 return myCustomCondition; } } }实战优势#1. 即时调试#void Update() { // Animancer - 实时监控 var current = _animancer.States.Current; if (current != null) { Debug.Log($&#34;Playing: {current.Key}&#34;); Debug.Log($&#34;Time: {current.Time}/{current.Length}&#34;); Debug.Log($&#34;Progress: {current.NormalizedTime * 100}%&#34;); } }2. 精确控制#// 完全掌控动画播放 var state = _animancer.Play(_attack); // 随时可以： state.Time = 0.5f; // 跳转到0.5秒 state.NormalizedTime = 0.5f; // 跳转到50% state.Speed = 2f; // 2倍速 state.Weight = 0.5f; // 50%权重 state.IsPlaying = false; // 暂停3. 条件检查#// 检查为什么无法切换状态 if (!_walkState.CanEnterState) { Debug.Log(&#34;无法进入Walk状态，原因：&#34;); // 自定义的条件检查 if (!IsGrounded()) Debug.Log(&#34;- 不在地面上&#34;); if (IsStunned()) Debug.Log(&#34;- 被击晕&#34;); if (IsDead()) Debug.Log(&#34;- 已死亡&#34;); }最佳实践#✅ 利用透明性优势#// 1. 实时监控 void OnGUI() { var current = _animancer.States.Current; if (current != null) { GUILayout.Label($&#34;Current: {current.Key}&#34;); GUILayout.Label($&#34;Weight: {current.Weight:F2}&#34;); GUILayout.Label($&#34;Time: {current.Time:F2}s&#34;); } } // 2. 详细日志 void LogAnimationState(AnimancerState state) { Debug.Log($&#34;=== Animation State ===&#34;); Debug.Log($&#34;Clip: {state.Clip.name}&#34;); Debug.Log($&#34;Length: {state.Length}s&#34;); Debug.Log($&#34;Speed: {state.Speed}x&#34;); Debug.Log($&#34;Weight: {state.Weight}&#34;); Debug.Log($&#34;IsPlaying: {state.IsPlaying}&#34;); Debug.Log($&#34;IsLooping: {state.IsLooping}&#34;); } // 3. 条件追踪 void TraceStateTransition() { var previous = _animancer.States.Previous; var current = _animancer.States.Current; Debug.Log($&#34;Transition: {previous?.Key} → {current?.Key}&#34;); }参考资料#📚 相关文档#animancer-why animancer-simplicity animancer-fsm 文档版本: 1.0 最后更新: 2025-12-25

Animancer Events 官方文档#📋 目录#概述 两种事件系统对比 核心概念 基础使用方法 代码示例 最佳实践 FAQ常见问题 参考资料 概述#Animancer Events 是一个强大的事件系统，允许你在动画播放过程中的特定时刻触发回调函数。
🎯 典型应用场景#场景 说明 事件触发时机 高尔夫挥杆 击打球的精确时刻 挥杆到达最低点时 脚步声 行走时播放脚步音效 脚触地时刻 攻击检测 武器伤害判定 武器挥舞到攻击范围时 特效触发 播放视觉特效 动画关键帧时刻 动画切换 连击系统、动画序列 当前动画结束时 两种事件系统对比#Animancer 支持两种事件系统，各有优缺点：
📊 对比表#特性 Animation Events
(Unity内置) Animancer Events
(自定义系统) 定义位置 AnimationClip内部 独立于AnimationClip 灵活性 所有使用该clip的状态共享事件 同一动画可使用不同事件集 回调位置 必须在同一GameObject的MonoBehaviour 可从任何位置注册 性能 效率较低，可能产生GC 使用C#委托，性能更优 配置方式 仅在AnimationClip中配置 检查器+代码 运行时修改 不支持 支持动态添加 兼容性 与Unity Animator完全相同 Animancer专属 ✅ Animation Events（Unity内置）#// Animation Events 需要在同一GameObject的MonoBehaviour中定义方法 public class CharacterController : MonoBehaviour { // 这个方法名必须与AnimationClip中的Event Name完全一致 public void PlayFootstepSound() { Debug.Log(&#34;脚步声触发&#34;); } // Animation Events可以接收参数 public void OnAttackHit(int damage) { Debug.Log($&#34;攻击伤害: {damage}&#34;); } }优点：
Unity原生支持，与Animator完全兼容 在Animation窗口中可视化编辑 无需额外学习成本 缺点：
必须在同一GameObject上 所有使用该clip的地方共享相同事件 运行时无法修改 性能开销较大 ✅ Animancer Events（推荐）#public class CharacterController : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _WalkTransition; void Start() { // 可以从任何位置注册回调 var state = _Animancer.Play(_WalkTransition); // 添加事件（使用时间） state.Events(this).Add(0.3f, PlayFootstep); state.Events(this).Add(0.7f, PlayFootstep); // 添加结束事件 state.Events(this).OnEnd = OnWalkEnd; } void PlayFootstep() { Debug.Log(&#34;脚步声&#34;); } void OnWalkEnd() { Debug.Log(&#34;行走动画结束&#34;); } }优点：
完全灵活的回调注册位置 同一动画可以有不同事件配置 支持运行时动态添加/移除 性能优异（C#委托） 支持Lambda表达式 缺点：
Animancer专属API 需要学习新的事件系统 核心概念#🎬 事件时间表示方式#Animancer Events 支持两种时间表示：
// 1. 绝对时间（秒） state.Events(this).Add(1.5f, MyCallback); // 在1.5秒时触发 // 2. 归一化时间（0-1） state.Events(this).AddNormalized(0.5f, MyCallback); // 在动画50%时触发📦 事件序列结构#AnimancerState └── AnimancerEvent.Sequence（事件序列） ├── Event 1（时间: 0.3s, 回调: PlayFootstep） ├── Event 2（时间: 0.7s, 回调: PlayFootstep） └── End Event（时间: NormalizedEndTime, 回调: OnAnimationEnd）🔄 事件触发逻辑#git remote add origin https://github.com/mickorz/NewskyGameBlog.git
播放动画 → 时间推进 → 检查事件 → 触发回调 → 继续播放 ↓ 时间 &gt;= 事件时间？ ├─ 是 → 调用事件回调 └─ 否 → 跳过基础使用方法#方法1：Inspector配置（推荐新手）#步骤：
创建 Transition [SerializeField] private ClipTransition _AttackTransition;在Inspector中配置事件
选中Transition 展开 &ldquo;Events&rdquo; 面板 点击 &ldquo;+&rdquo; 添加事件 设置时间和回调 设置回调
void Start() { // 自动应用Inspector中配置的事件 _Animancer.Play(_AttackTransition); }方法2：代码配置（推荐高级用户）#public class WeaponController : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; void PerformAttack() { var state = _Animancer.Play(_AttackClip); // 添加攻击检测事件（归一化时间） state.Events(this).AddNormalized(0.6f, CheckHit); // 添加结束事件 state.Events(this).OnEnd = OnAttackEnd; } void CheckHit() { Debug.Log(&#34;检测攻击命中&#34;); // 执行伤害判定逻辑 } void OnAttackEnd() { Debug.Log(&#34;攻击动画结束，返回Idle&#34;); _Animancer.Play(_IdleClip); } }代码示例#示例1：脚步声系统#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 脚步声系统示例 /// 在行走/跑步动画中播放脚步音效 /// &lt;/summary&gt; public class FootstepSoundSystem : MonoBehaviour { [Header(&#34;组件引用&#34;)] [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AudioSource _AudioSource; [Header(&#34;动画配置&#34;)] [SerializeField] private ClipTransition _WalkTransition; [SerializeField] private ClipTransition _RunTransition; [Header(&#34;音效配置&#34;)] [SerializeField] private AudioClip[] _FootstepSounds; void Update() { float speed = Input.GetAxis(&#34;Vertical&#34;); if (speed &gt; 0.5f) { PlayRunWithFootsteps(); } else if (speed &gt; 0.1f) { PlayWalkWithFootsteps(); } } void PlayWalkWithFootsteps() { var state = _Animancer.Play(_WalkTransition); // 清除之前的事件 state.Events(this).Clear(); // 行走动画通常有2个脚步点 state.Events(this).AddNormalized(0.2f, PlayFootstepSound); // 左脚 state.Events(this).AddNormalized(0.7f, PlayFootstepSound); // 右脚 } void PlayRunWithFootsteps() { var state = _Animancer.Play(_RunTransition); state.Events(this).Clear(); // 跑步动画脚步更快 state.Events(this).AddNormalized(0.25f, PlayFootstepSound); state.Events(this).AddNormalized(0.75f, PlayFootstepSound); } void PlayFootstepSound() { if (_FootstepSounds.Length == 0) return; // 随机播放一个脚步声 var clip = _FootstepSounds[Random.Range(0, _FootstepSounds.Length)]; _AudioSource.PlayOneShot(clip); } }示例2：攻击连击系统#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 攻击连击系统 /// 使用Animancer Events实现连击窗口检测 /// &lt;/summary&gt; public class ComboAttackSystem : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _Attack1; [SerializeField] private ClipTransition _Attack2; [SerializeField] private ClipTransition _Attack3; [SerializeField] private ClipTransition _Idle; private int _currentCombo = 0; private bool _canCombo = false; void Update() { if (Input.GetKeyDown(KeyCode.Mouse0)) { if (_currentCombo == 0 || _canCombo) { PerformNextAttack(); } } } void PerformNextAttack() { _currentCombo++; _canCombo = false; AnimancerState state = null; switch (_currentCombo) { case 1: state = _Animancer.Play(_Attack1); break; case 2: state = _Animancer.Play(_Attack2); break; case 3: state = _Animancer.Play(_Attack3); break; } if (state != null) { // 连击窗口：在动画60%-90%之间可以进行下一次攻击 state.Events(this).AddNormalized(0.6f, OpenComboWindow); state.Events(this).AddNormalized(0.9f, CloseComboWindow); // 攻击判定点：在动画50%时检测命中 state.Events(this).AddNormalized(0.5f, CheckHit); // 结束事件 state.Events(this).OnEnd = OnAttackEnd; } } void OpenComboWindow() { _canCombo = true; Debug.Log(&#34;连击窗口打开&#34;); } void CloseComboWindow() { _canCombo = false; Debug.Log(&#34;连击窗口关闭&#34;); } void CheckHit() { Debug.Log($&#34;执行攻击 {_currentCombo} 的伤害判定&#34;); // 实际项目中这里执行碰撞检测、伤害计算等 } void OnAttackEnd() { if (!_canCombo || _currentCombo &gt;= 3) { // 连击结束，返回Idle _currentCombo = 0; _Animancer.Play(_Idle); Debug.Log(&#34;连击结束&#34;); } } }示例3：技能特效触发#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 技能特效系统 /// 在技能动画的关键帧触发粒子特效 /// &lt;/summary&gt; public class SkillEffectSystem : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _FireballSkill; [SerializeField] private ClipTransition _IceSpellSkill; [SerializeField] private ParticleSystem _FireballEffect; [SerializeField] private ParticleSystem _IceEffect; [SerializeField] private Transform _CastPoint; void Update() { if (Input.GetKeyDown(KeyCode.Alpha1)) { CastFireball(); } else if (Input.GetKeyDown(KeyCode.Alpha2)) { CastIceSpell(); } } void CastFireball() { var state = _Animancer.Play(_FireballSkill); // 事件序列：准备 → 施法 → 发射 state.Events(this).Clear(); // 0.3s: 手部开始聚集火焰 state.Events(this).Add(0.3f, () =&gt; { Debug.Log(&#34;开始聚集火焰能量&#34;); // 播放聚集特效 }); // 0.8s: 发射火球 state.Events(this).Add(0.8f, () =&gt; { Debug.Log(&#34;发射火球！&#34;); Instantiate(_FireballEffect, _CastPoint.position, _CastPoint.rotation); }); // 结束事件 state.Events(this).OnEnd = () =&gt; { Debug.Log(&#34;施法完成&#34;); _Animancer.Play(_IdleClip); }; } void CastIceSpell() { var state = _Animancer.Play(_IceSpellSkill); state.Events(this).Clear(); // 使用归一化时间（更稳定） state.Events(this).AddNormalized(0.5f, () =&gt; { Debug.Log(&#34;冰霜爆发！&#34;); _IceEffect.transform.position = transform.position; _IceEffect.Play(); }); state.Events(this).OnEnd = () =&gt; { _Animancer.Play(_IdleClip); }; } [SerializeField] private AnimationClip _IdleClip; }示例4：事件参数传递#using Animancer; using UnityEngine; using System; /// &lt;summary&gt; /// 事件参数传递示例 /// 演示如何在事件中传递数据 /// &lt;/summary&gt; public class EventParameterExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _Attack; void PerformAttack(int damage, string attackType) { var state = _Animancer.Play(_Attack); // 方法1：使用Lambda捕获变量 state.Events(this).AddNormalized(0.5f, () =&gt; { OnAttackHit(damage, attackType); }); // 方法2：使用闭包 float criticalChance = 0.2f; state.Events(this).AddNormalized(0.5f, () =&gt; { bool isCritical = UnityEngine.Random.value &lt; criticalChance; int finalDamage = isCritical ? damage * 2 : damage; OnAttackHit(finalDamage, attackType + (isCritical ? &#34; (暴击!)&#34; : &#34;&#34;)); }); } void OnAttackHit(int damage, string attackType) { Debug.Log($&#34;攻击类型: {attackType}, 伤害: {damage}&#34;); } // 示例调用 void Update() { if (Input.GetKeyDown(KeyCode.Alpha1)) { PerformAttack(50, &#34;轻攻击&#34;); } else if (Input.GetKeyDown(KeyCode.Alpha2)) { PerformAttack(100, &#34;重攻击&#34;); } } }示例5：事件管理器（高级）#using Animancer; using UnityEngine; using System.Collections.Generic; /// &lt;summary&gt; /// 动画事件管理器 /// 集中管理所有动画事件，方便维护和扩展 /// &lt;/summary&gt; public class AnimationEventManager : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; // 事件配置数据 [System.Serializable] public class AnimEventConfig { public string AnimationName; public List&lt;EventPoint&gt; Events; } [System.Serializable] public class EventPoint { public float NormalizedTime; public string EventName; } [SerializeField] private List&lt;AnimEventConfig&gt; _EventConfigs; private Dictionary&lt;string, System.Action&gt; _eventCallbacks; void Awake() { // 注册所有事件回调 _eventCallbacks = new Dictionary&lt;string, System.Action&gt; { { &#34;PlayFootstep&#34;, PlayFootstep }, { &#34;CheckHit&#34;, CheckHit }, { &#34;SpawnEffect&#34;, SpawnEffect }, // 更多事件... }; } /// &lt;summary&gt; /// 播放动画并自动应用配置的事件 /// &lt;/summary&gt; public AnimancerState PlayWithEvents(AnimationClip clip) { var state = _Animancer.Play(clip); ApplyEvents(state, clip.name); return state; } void ApplyEvents(AnimancerState state, string animName) { var config = _EventConfigs.Find(c =&gt; c.AnimationName == animName); if (config == null) return; state.Events(this).Clear(); foreach (var eventPoint in config.Events) { if (_eventCallbacks.TryGetValue(eventPoint.EventName, out var callback)) { state.Events(this).AddNormalized(eventPoint.NormalizedTime, callback); Debug.Log($&#34;添加事件: {eventPoint.EventName} @ {eventPoint.NormalizedTime:P0}&#34;); } else { Debug.LogWarning($&#34;未找到事件回调: {eventPoint.EventName}&#34;); } } } // 事件回调实现 void PlayFootstep() =&gt; Debug.Log(&#34;脚步声&#34;); void CheckHit() =&gt; Debug.Log(&#34;攻击检测&#34;); void SpawnEffect() =&gt; Debug.Log(&#34;生成特效&#34;); }最佳实践#✅ DO（推荐做法）#使用 Transition 播放动画 // ✅ 好：使用Transition，自动应用Inspector配置的事件 var state = _Animancer.Play(_AttackTransition);使用归一化时间（0-1） // ✅ 好：归一化时间不受动画长度影响 state.Events(this).AddNormalized(0.5f, Callback);清除旧事件避免重复触发 // ✅ 好：每次播放前清除旧事件 state.Events(this).Clear(); state.Events(this).Add(0.5f, NewCallback);使用 End Event 而非手动计算 // ✅ 好：使用OnEnd state.Events(this).OnEnd = OnAnimationEnd;使用 Lambda 传递参数 // ✅ 好：清晰的参数传递 int damage = 50; state.Events(this).Add(0.5f, () =&gt; DealDamage(damage));❌ DON&rsquo;T（避免做法）#直接播放 AnimationClip // ❌ 差：直接播放Clip，无法使用Inspector配置的事件 var state = _Animancer.Play(_AttackClip);硬编码绝对时间 // ❌ 差：如果动画长度改变，时间点就不对了 state.Events(this).Add(1.5f, Callback);忘记清除事件 // ❌ 差：重复播放会累积事件 state.Events(this).Add(0.5f, Callback); // 可能被多次添加使用 Update 轮询动画时间 // ❌ 差：性能低且不精确 void Update() { if (state.Time &gt;= 0.5f &amp;&amp; !hasTriggered) { Callback(); hasTriggered = true; } }在事件中执行耗时操作 // ❌ 差：阻塞主线程 state.Events(this).Add(0.5f, () =&gt; { Thread.Sleep(100); // 卡顿！ });FAQ常见问题#Q1: 如何在同一时间点添加多个事件？#A: 多次调用 Add 方法即可：
var state = _Animancer.Play(_Attack); state.Events(this).AddNormalized(0.5f, PlaySound); state.Events(this).AddNormalized(0.5f, SpawnEffect); state.Events(this).AddNormalized(0.5f, CheckHit);Q2: 事件会在循环动画中重复触发吗？#A: 是的，循环动画每次循环都会触发事件：
// Loop动画会在每次循环时触发事件 var state = _Animancer.Play(_WalkClip); state.IsLooping = true; state.Events(this).AddNormalized(0.3f, PlayFootstep); // 每次循环都触发Q3: 如何临时禁用某个事件？#A: 方法1是移除事件，方法2是使用标志位：
// 方法1：移除事件 state.Events(this).Clear(); // 方法2：使用标志位 bool enableEvent = false; state.Events(this).Add(0.5f, () =&gt; { if (enableEvent) Callback(); });Q4: Animancer Events 和 Animation Events 可以混用吗？#A: 可以，两者完全独立：
// Animation Events（在Clip中定义） public void UnityEventCallback() { } // Animancer Events（代码定义） state.Events(this).Add(0.5f, AnimancerCallback);Q5: 事件回调的 this 参数是什么？#A: 这是用于自动清理的上下文对象：
// this 是当前MonoBehaviour // 当该对象被销毁时，事件会自动清理 state.Events(this).Add(0.5f, Callback); // 不传this也可以，但需要手动管理生命周期 state.Events().Add(0.5f, Callback); // ⚠️ 需要手动清理Q6: 如何调试事件没有触发的问题？#A: 检查以下几点：
// 1. 确认动画在播放 Debug.Log($&#34;动画播放中: {state.IsPlaying}&#34;); // 2. 确认时间有经过事件点 Debug.Log($&#34;当前时间: {state.Time}, 事件时间: 0.5&#34;); // 3. 检查事件是否被添加 var events = state.Events(); Debug.Log($&#34;事件数量: {events.Count}&#34;); // 4. 添加日志到回调中 state.Events(this).Add(0.5f, () =&gt; { Debug.Log(&#34;事件触发！&#34;); Callback(); });Q7: 为什么有时候事件触发两次？#A: 可能原因：
// 原因1：没有清除旧事件 state.Events(this).Clear(); // 添加这行 // 原因2：重复播放动画 if (!state.IsPlaying) // 添加检查 { _Animancer.Play(_Clip); } // 原因3：动画循环 state.IsLooping = false; // 如果不需要循环Q8: 如何在事件中切换动画？#A: 直接调用 Play 即可：
state.Events(this).OnEnd = () =&gt; { _Animancer.Play(_NextClip); // 安全 };参考资料#📚 相关文档#Animancer Events - Animation Animancer Events - Animancer Events Animancer Events - Usage Animancer Events - End Events 🔗 官方链接#Animancer 官方文档 Unity Animation Events 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer Events - Behaviour 官方文档#📋 目录#概述 核心行为机制 循环动画中的事件 End Events行为 高级特性 代码示例 最佳实践 FAQ常见问题 参考资料 概述#本文档详细解释 Animancer Events 的工作原理和触发机制，特别是在不同动画状态（循环/非循环）下的行为差异。
核心行为机制#🎯 触发时机#事件触发取决于动画类型：
动画类型 触发行为 非循环动画 &ldquo;Once on the frame when the animation passes the specified time&rdquo;
动画通过指定时间点时触发一次 循环动画 &ldquo;Every loop on the frame when the animation passes the specified time&rdquo;
每次循环通过指定时间点时都触发 📊 触发机制图解#非循环动画#时间轴: 0 ───────────→ 0.5 ───────────→ 1.0 (结束) ↑ 事件触发 1次 动画播放: ▬▬▬▬▬▬▬▬→ ⚡ ▬▬▬▬▬▬▬▬→ ⏹️循环动画#循环1: 0 → 0.5 → 1.0 → (重新开始) ↑ 事件触发 循环2: 0 → 0.5 → 1.0 → (重新开始) ↑ 事件再次触发 循环3: 0 → 0.5 → 1.0 → (重新开始) ↑ 事件再次触发 动画播放: 🔄▬▬→ ⚡ ▬▬→ 🔄▬▬→ ⚡ ▬▬→ 🔄▬▬→ ⚡ ▬▬→循环动画中的事件#🔗 归一化时间约束#重要约束：循环动画中的事件必须满足 0 &lt;= normalizedTime &lt; 1
// ✅ 有效的归一化时间 state.Events.AddNormalized(0.0f, Callback); // 循环开始 state.Events.AddNormalized(0.5f, Callback); // 循环中间 state.Events.AddNormalized(0.99f, Callback); // 接近结束 // ❌ 无效的归一化时间（抛出 ArgumentOutOfRangeException） state.Events.AddNormalized(1.0f, Callback); // 超出范围 state.Events.AddNormalized(1.5f, Callback); // 超出范围⚠️ 异常处理#// 超出范围会在更新时抛出异常 try { state.Events.AddNormalized(1.0f, MyCallback); } catch (ArgumentOutOfRangeException ex) { Debug.LogError($&#34;事件时间超出循环范围: {ex.Message}&#34;); }🎯 AlmostOne 常量#对于需要在循环结束时触发的事件，使用 AnimancerEvent.AlmostOne：
// 使用AlmostOne表示接近1但小于1的最大float值 state.Events.AddNormalized(AnimancerEvent.AlmostOne, OnLoopEnd); // 等效于 state.Events.AddNormalized(0.999999f, OnLoopEnd);🔄 快速循环行为#特性：如果动画在一帧内播放多个循环，事件会按比例触发。
// 示例：动画速度非常快，1帧播放3次循环 state.Speed = 100f; // 如果在0.5处有事件 state.Events.AddNormalized(0.5f, OnMidLoop); // 那么该帧会触发3次OnMidLoop回调！End Events行为#🎯 End Events 特殊机制#&ldquo;End Events trigger on every frame when the animation has passed the specified time&rdquo;
End Events 在动画通过指定时间后的每一帧都触发，独立于循环状态。
📊 End Events vs 普通Events#特性 普通Events End Events 触发次数 通过时间点时触发一次 通过后每帧都触发 循环依赖 受循环影响 不受循环影响 典型用途 特定时刻的事件 动画结束后的持续检测 📝 End Events 示例#using Animancer; using UnityEngine; /// &lt;summary&gt; /// End Events 行为示例 /// &lt;/summary&gt; public class EndEventsBehaviourExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; void Start() { var state = _Animancer.Play(_AttackClip); state.IsLooping = false; // OnEnd 会在动画结束后的每一帧调用 state.Events.OnEnd = OnAttackEnd; } int _endCallCount = 0; void OnAttackEnd() { _endCallCount++; Debug.Log($&#34;OnEnd触发第 {_endCallCount} 次&#34;); // 通常在第一次触发时切换动画 if (_endCallCount == 1) { _Animancer.Play(_IdleClip); } } [SerializeField] private AnimationClip _IdleClip; }高级特性#⏱️ 时间修改（Time Modification）#重要：修改 AnimancerState.Time 会阻止该帧的后续事件触发。
void OnEventA() { var state = AnimancerEvent.Current.State; // 直接修改Time会跳过中间的事件 state.Time = 2.0f; // 阻止该帧其他事件触发 }🎯 MoveTime 方法#使用 MoveTime 方法触发中间事件：
void OnEventA() { var state = AnimancerEvent.Current.State; // MoveTime 会触发中间的所有事件 state.MoveTime(2.0f, true); // ✅ 触发中间事件 }🚫 事件序列修改限制#约束：事件序列不能被自己的回调修改。
void OnEvent() { var state = AnimancerEvent.Current.State; // ❌ 错误：不能在回调中修改事件序列 // state.Events.Add(0.8f, AnotherCallback); // 会抛出异常 // ✅ 正确：延迟到下一帧修改 UnityEngine.Coroutines.StartCoroutine(ModifyEventsNextFrame(state)); } IEnumerator ModifyEventsNextFrame(AnimancerState state) { yield return null; state.Events.Add(0.8f, AnotherCallback); // ✅ 安全 }🎚️ Mixer 上的事件#事件可以附加到 Mixer 或其子动画：
// 附加到Mixer：根据加权平均时间触发 mixerState.Events.Add(0.5f, OnMixerEvent); // 附加到子动画：根据子动画自身时间触发 mixerState.GetChild(0).Events.Add(0.5f, OnChildEvent);🎮 Controller State 兼容性#限制：事件技术上支持 Controller States，但在检测内部 Animator 行为方面有限制。
// Controller State 的事件支持有限 var controllerState = _Animancer.Play(animatorController); controllerState.Events.Add(0.5f, Callback); // 可能不可靠🔄 IUpdatable 接口替代方案#对于自定义动画驱动逻辑，推荐实现 IUpdatable 接口：
public class CustomAnimationLogic : MonoBehaviour, IUpdatable { public void Update() { // 自定义更新逻辑 CheckCustomConditions(); } void CheckCustomConditions() { // 根据动画状态执行逻辑 } }代码示例#示例1：循环 vs 非循环事件#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 循环和非循环事件对比示例 /// &lt;/summary&gt; public class LoopingBehaviourExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _WalkClip; [SerializeField] private AnimationClip _AttackClip; void Start() { TestLoopingAnimation(); TestNonLoopingAnimation(); } void TestLoopingAnimation() { var walkState = _Animancer.Play(_WalkClip); walkState.IsLooping = true; // 事件会在每次循环时触发 walkState.Events.AddNormalized(0.3f, () =&gt; { Debug.Log($&#34;[循环] 左脚触地 @ 时间={walkState.Time}&#34;); }); walkState.Events.AddNormalized(0.7f, () =&gt; { Debug.Log($&#34;[循环] 右脚触地 @ 时间={walkState.Time}&#34;); }); // 使用AlmostOne在循环结束时触发 walkState.Events.AddNormalized(AnimancerEvent.AlmostOne, () =&gt; { Debug.Log($&#34;[循环] 循环结束 @ 时间={walkState.Time}&#34;); }); } void TestNonLoopingAnimation() { var attackState = _Animancer.Play(_AttackClip); attackState.IsLooping = false; // 事件只触发一次 attackState.Events.AddNormalized(0.5f, () =&gt; { Debug.Log($&#34;[非循环] 攻击判定 @ 时间={attackState.Time}&#34;); }); // End Event 在动画结束后每帧触发 attackState.Events.OnEnd = () =&gt; { Debug.Log(&#34;[非循环] 动画结束 (每帧触发)&#34;); // 通常在第一次触发时切换动画 if (!_hasTransitioned) { _Animancer.Play(_WalkClip); _hasTransitioned = true; } }; } private bool _hasTransitioned = false; }示例2：快速循环事件触发#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 快速循环事件触发示例 /// 演示高速播放时事件的多次触发 /// &lt;/summary&gt; public class FastLoopingExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _SpinClip; void Start() { var state = _Animancer.Play(_SpinClip); state.IsLooping = true; // 正常速度 state.Speed = 1f; // 在中点添加事件 int triggerCount = 0; state.Events.AddNormalized(0.5f, () =&gt; { triggerCount++; Debug.Log($&#34;事件触发 #{triggerCount}&#34;); }); // 2秒后加速 StartCoroutine(SpeedUpAfterDelay()); } System.Collections.IEnumerator SpeedUpAfterDelay() { yield return new WaitForSeconds(2f); Debug.Log(&#34;加速到10倍速度！&#34;); var state = _Animancer.States.Current; state.Speed = 10f; // 现在事件会在单帧内多次触发 yield return new WaitForSeconds(2f); Debug.Log(&#34;加速到100倍速度！&#34;); state.Speed = 100f; // 可能在一帧内触发多次 } }示例3：Time vs MoveTime#using Animancer; using UnityEngine; /// &lt;summary&gt; /// Time vs MoveTime 对比示例 /// 演示两种时间修改方式的区别 /// &lt;/summary&gt; public class TimeMoveTimeExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _TestClip; void Start() { TestDirectTimeModification(); TestMoveTimeMethod(); } void TestDirectTimeModification() { var state = _Animancer.Play(_TestClip); // 添加多个事件 state.Events.Add(0.5f, OnEvent1); state.Events.Add(1.0f, OnEvent2); state.Events.Add(1.5f, OnEvent3); state.Events.Add(2.0f, OnEvent4); // 在Event1中直接修改Time void OnEvent1() { Debug.Log(&#34;Event1触发&#34;); // 直接跳到2.0s，跳过Event2和Event3 state.Time = 2.0f; Debug.Log(&#34;跳到2.0s，Event2和Event3被跳过&#34;); } } void TestMoveTimeMethod() { var state = _Animancer.Play(_TestClip); state.Events.Add(0.5f, OnEventA); state.Events.Add(1.0f, OnEventB); state.Events.Add(1.5f, OnEventC); state.Events.Add(2.0f, OnEventD); void OnEventA() { Debug.Log(&#34;EventA触发&#34;); // 使用MoveTime移动到2.0s，触发中间事件 state.MoveTime(2.0f, fireEvents: true); Debug.Log(&#34;移动到2.0s，EventB和EventC也被触发&#34;); } } void OnEvent2() =&gt; Debug.Log(&#34;Event2触发&#34;); void OnEvent3() =&gt; Debug.Log(&#34;Event3触发&#34;); void OnEvent4() =&gt; Debug.Log(&#34;Event4触发&#34;); void OnEventB() =&gt; Debug.Log(&#34;EventB触发&#34;); void OnEventC() =&gt; Debug.Log(&#34;EventC触发&#34;); void OnEventD() =&gt; Debug.Log(&#34;EventD触发&#34;); }示例4：Mixer上的事件#using Animancer; using UnityEngine; /// &lt;summary&gt; /// Mixer事件示例 /// 演示在Mixer和子动画上附加事件的区别 /// &lt;/summary&gt; public class MixerEventsExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _IdleClip; [SerializeField] private AnimationClip _WalkClip; [SerializeField] private AnimationClip _RunClip; void Start() { // 创建Mixer var mixer = new LinearMixerState(_Animancer.Graph) { { _IdleClip, 0.0f }, { _WalkClip, 0.5f }, { _RunClip, 1.0f } }; _Animancer.Play(mixer); // 在Mixer上添加事件：根据加权平均时间触发 mixer.Events.AddNormalized(0.5f, () =&gt; { Debug.Log($&#34;Mixer事件触发 @ 加权平均时间50%&#34;); }); // 在子动画上添加事件：根据子动画自身时间触发 mixer.GetChild(1).Events.AddNormalized(0.5f, () =&gt; { Debug.Log(&#34;Walk子动画事件触发 @ Walk时间50%&#34;); }); mixer.GetChild(2).Events.AddNormalized(0.5f, () =&gt; { Debug.Log(&#34;Run子动画事件触发 @ Run时间50%&#34;); }); // 调整Mixer参数 mixer.Parameter = 0.5f; // Walk } }最佳实践#✅ DO（推荐做法）#循环动画使用合法范围 // ✅ 好：归一化时间在[0, 1)范围内 state.Events.AddNormalized(0.5f, Callback); state.Events.AddNormalized(AnimancerEvent.AlmostOne, OnLoopEnd);End Event 中检查是否首次触发 // ✅ 好：避免重复处理 bool _hasEnded = false; state.Events.OnEnd = () =&gt; { if (!_hasEnded) { _hasEnded = true; HandleAnimationEnd(); } };使用 MoveTime 触发中间事件 // ✅ 好：使用MoveTime state.MoveTime(targetTime, fireEvents: true);延迟修改事件序列 // ✅ 好：下一帧修改 StartCoroutine(ModifyEventsNextFrame());❌ DON&rsquo;T（避免做法）#循环动画使用 1.0 或更大的归一化时间 // ❌ 差：超出范围 state.Events.AddNormalized(1.0f, Callback); // 抛出异常忘记处理 End Event 的重复触发 // ❌ 差：每帧都会切换动画 state.Events.OnEnd = () =&gt; { _Animancer.Play(_NextClip); // 重复执行！ };直接修改 Time 期望触发中间事件 // ❌ 差：中间事件不会触发 state.Time = 2.0f; // 跳过中间事件在事件回调中修改事件序列 // ❌ 差：抛出异常 void OnEvent() { state.Events.Add(0.8f, AnotherCallback); // 错误！ }FAQ常见问题#Q1: 为什么循环动画不能使用 1.0 作为归一化时间？#A: 循环动画的时间范围是 [0, 1)（左闭右开区间），1.0 表示下一次循环的开始（等同于 0.0）。如果允许 1.0，会导致歧义。使用 AnimancerEvent.AlmostOne 代替。
Q2: End Event 为什么每帧都触发？#A: End Event 的设计目的是检测&quot;动画是否已结束&quot;的状态，而不是&quot;动画刚刚结束&quot;的事件。因此只要动画时间 &gt;= End Time，每帧都会触发。
解决方案：
bool _hasHandledEnd = false; state.Events.OnEnd = () =&gt; { if (!_hasHandledEnd) { _hasHandledEnd = true; // 只执行一次 } };Q3: 如何在事件中跳转到另一个时间点？#A: 根据需求选择：
// 方法1：跳过中间事件 state.Time = 2.0f; // 方法2：触发中间事件 state.MoveTime(2.0f, fireEvents: true);Q4: 快速播放时事件触发多次怎么办？#A: 这是正常行为。如果只想触发一次，使用标志位：
bool _hasTriggered = false; state.Events.AddNormalized(0.5f, () =&gt; { if (!_hasTriggered) { _hasTriggered = true; HandleEvent(); } });Q5: 可以在事件回调中添加新事件吗？#A: 不能直接添加，需要延迟到下一帧：
void OnEvent() { StartCoroutine(AddEventNextFrame()); } IEnumerator AddEventNextFrame() { yield return null; state.Events.Add(0.8f, NewCallback); }参考资料#📚 相关文档#Animancer Events 主页 Animancer Events - Usage End Events 🔗 API 参考#AnimancerEvent.AlmostOne AnimancerState.MoveTime() AnimancerState.Time IUpdatable 接口 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer Events - Parameters 官方文档#📋 目录#概述 核心概念 使用带参数的回调 内置参数类型 自定义参数类型 代码示例 最佳实践 FAQ常见问题 参考资料 概述#Animancer Events 默认使用无参数回调，但支持通过 AnimancerEvent.Parameter 系统传递参数值给事件回调。
🎯 核心特性#&ldquo;事件回调默认为无参数，但可以通过设置 AnimancerEvent.Parameter 选项来传递参数值&rdquo;
核心概念#📦 参数系统架构#AnimancerEvent ├── 无参数回调 (默认) │ └── Action callback │ └── 带参数回调 ├── AnimancerEvent.Parameter&lt;T&gt; (引用类型) └── AnimancerEvent.ParameterBoxed&lt;T&gt; (值类型)🔍 参数类型分类#参数类型 基类 适用于 示例 引用类型 AnimancerEvent.Parameter&lt;T&gt; class AudioSource, GameObject 值类型 AnimancerEvent.ParameterBoxed&lt;T&gt; struct, enum Vector3, int, SoundType 使用带参数的回调#🎯 基础语法#使用泛型方法注册带参数的回调：
// 泛型语法指定参数类型 _Animancer.Events.AddTo&lt;AudioSource&gt;(_EventName, PlaySound); _Animation.Events.AddCallback&lt;AudioSource&gt;(_EventName, PlaySound);📚 三种配置方式#所有三种事件配置方式都支持参数：
1. Central Events（中央事件）#void Awake() { // 注册带参数的全局事件 _Animancer.Events.AddTo&lt;AudioSource&gt;(&#34;PlaySound&#34;, PlaySound); } void PlaySound(AudioSource audioSource) { audioSource.Play(); }2. Transition Events（Transition事件）#void Start() { // 为Transition注册带参数回调 _AttackTransition.Events.AddCallback&lt;int&gt;(&#34;Hit&#34;, OnHit); } void OnHit(int damage) { Debug.Log($&#34;造成 {damage} 点伤害&#34;); }3. State Events（状态事件）#void PerformAttack() { var state = _Animancer.Play(_AttackClip); // 在状态上注册带参数回调 state.Events.AddCallback&lt;Vector3&gt;(&#34;SpawnEffect&#34;, SpawnEffect); } void SpawnEffect(Vector3 position) { Instantiate(_EffectPrefab, position, Quaternion.identity); }内置参数类型#Animancer 内置支持常见参数类型：
📝 常用类型#// Unity常用类型（引用类型） AudioSource GameObject Transform ParticleSystem AudioClip // 值类型 int float bool Vector3 Quaternion📊 使用示例#using Animancer; using UnityEngine; public class BuiltInParameterExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; void Awake() { // AudioSource参数 _Animancer.Events.AddTo&lt;AudioSource&gt;(&#34;PlaySound&#34;, PlaySound); // int参数 _Animancer.Events.AddTo&lt;int&gt;(&#34;Damage&#34;, ApplyDamage); // Vector3参数 _Animancer.Events.AddTo&lt;Vector3&gt;(&#34;SpawnAt&#34;, SpawnEffect); // bool参数 _Animancer.Events.AddTo&lt;bool&gt;(&#34;SetActive&#34;, SetWeaponActive); } void PlaySound(AudioSource source) =&gt; source.Play(); void ApplyDamage(int damage) =&gt; Debug.Log($&#34;伤害: {damage}&#34;); void SpawnEffect(Vector3 pos) =&gt; Debug.Log($&#34;生成特效 @ {pos}&#34;); void SetWeaponActive(bool active) =&gt; Debug.Log($&#34;武器激活: {active}&#34;); }自定义参数类型#🎨 创建自定义参数类型#根据类型分类选择基类：
引用类型（class）#[System.Serializable] public class ParameterAudioSource : Animancer.AnimancerEvent.Parameter&lt;AudioSource&gt; { }值类型（struct/enum）#[System.Serializable] public class ParameterVector3 : Animancer.AnimancerEvent.ParameterBoxed&lt;Vector3&gt; { } [System.Serializable] public class ParameterSoundType : Animancer.AnimancerEvent.ParameterBoxed&lt;SoundType&gt; { }📚 完整示例#using Animancer; using UnityEngine; // 定义枚举 public enum SoundType { Footstep, Jump, Land, Attack } // 创建参数类型 [System.Serializable] public class ParameterSoundType : AnimancerEvent.ParameterBoxed&lt;SoundType&gt; { } /// &lt;summary&gt; /// 自定义参数类型示例 /// &lt;/summary&gt; public class CustomParameterExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _WalkTransition; void Awake() { // 注册带自定义参数的事件 _Animancer.Events.AddTo&lt;SoundType&gt;(&#34;PlaySound&#34;, PlaySound); } void PlaySound(SoundType soundType) { Debug.Log($&#34;播放音效: {soundType}&#34;); switch (soundType) { case SoundType.Footstep: // 播放脚步声 break; case SoundType.Jump: // 播放跳跃音效 break; // ... } } }🔧 高级：实现 IInvokable 接口#对于更复杂的需求，可以直接实现 IInvokable 接口：
using Animancer; using UnityEngine; /// &lt;summary&gt; /// 自定义可调用事件 /// &lt;/summary&gt; [System.Serializable] public class CustomInvokable : IInvokable { public string EventName; public int Damage; public float Multiplier; public void Invoke(AnimancerState state) { Debug.Log($&#34;事件: {EventName}&#34;); Debug.Log($&#34;伤害: {Damage * Multiplier}&#34;); } }代码示例#示例1：Footstep Events（脚步声事件）#官方示例：&ldquo;Footstep Events示例演示了如何用参数区分左右脚事件&rdquo;
using Animancer; using UnityEngine; // 定义脚步类型枚举 public enum FootType { Left, Right } // 创建参数类型 [System.Serializable] public class ParameterFootType : AnimancerEvent.ParameterBoxed&lt;FootType&gt; { } /// &lt;summary&gt; /// 脚步声事件参数示例 /// 使用参数区分左右脚，避免创建重复的事件名称 /// &lt;/summary&gt; public class FootstepEventsExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _WalkTransition; [Header(&#34;音效&#34;)] [SerializeField] private AudioSource _AudioSource; [SerializeField] private AudioClip[] _LeftFootSounds; [SerializeField] private AudioClip[] _RightFootSounds; [Header(&#34;粒子特效&#34;)] [SerializeField] private ParticleSystem _DustEffect; [SerializeField] private Transform _LeftFoot; [SerializeField] private Transform _RightFoot; void Awake() { // 注册单个事件名，使用参数区分左右脚 _Animancer.Events.AddTo&lt;FootType&gt;(&#34;Footstep&#34;, OnFootstep); } void OnFootstep(FootType footType) { // 根据脚步类型播放不同音效 AudioClip[] sounds = footType == FootType.Left ? _LeftFootSounds : _RightFootSounds; if (sounds.Length &gt; 0) { var clip = sounds[Random.Range(0, sounds.Length)]; _AudioSource.PlayOneShot(clip); } // 在对应脚的位置生成粉尘特效 Transform foot = footType == FootType.Left ? _LeftFoot : _RightFoot; _DustEffect.transform.position = foot.position; _DustEffect.Play(); Debug.Log($&#34;{footType}脚触地&#34;); } } /* Inspector配置（在_WalkTransition中）： - Event 1: Time=0.3, Name=&#34;Footstep&#34;, Parameter=FootType.Left - Event 2: Time=0.7, Name=&#34;Footstep&#34;, Parameter=FootType.Right */示例2：武器系统参数#using Animancer; using UnityEngine; // 武器配置 [System.Serializable] public class WeaponConfig { public string Name; public int Damage; public float Range; public ParticleSystem HitEffect; } // 参数类型 [System.Serializable] public class ParameterWeaponConfig : AnimancerEvent.Parameter&lt;WeaponConfig&gt; { } /// &lt;summary&gt; /// 武器系统参数示例 /// 使用参数传递武器配置 /// &lt;/summary&gt; public class WeaponSystemExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [Header(&#34;武器配置&#34;)] [SerializeField] private WeaponConfig _SwordConfig; [SerializeField] private WeaponConfig _AxeConfig; [SerializeField] private WeaponConfig _SpearConfig; void Awake() { // 注册带武器配置参数的事件 _Animancer.Events.AddTo&lt;WeaponConfig&gt;(&#34;Attack&#34;, OnAttack); } void OnAttack(WeaponConfig weapon) { Debug.Log($&#34;攻击: {weapon.Name}&#34;); Debug.Log($&#34;伤害: {weapon.Damage}&#34;); Debug.Log($&#34;范围: {weapon.Range}&#34;); // 检测命中 CheckHit(weapon); // 播放特效 if (weapon.HitEffect != null) { weapon.HitEffect.Play(); } } void CheckHit(WeaponConfig weapon) { Collider[] hits = Physics.OverlapSphere( transform.position, weapon.Range ); foreach (var hit in hits) { if (hit.CompareTag(&#34;Enemy&#34;)) { hit.GetComponent&lt;Enemy&gt;()?.TakeDamage(weapon.Damage); } } } } public class Enemy : MonoBehaviour { public void TakeDamage(int damage) { } }示例3：技能特效参数#using Animancer; using UnityEngine; // 特效配置 [System.Serializable] public class EffectConfig { public GameObject EffectPrefab; public Vector3 LocalOffset; public float Lifetime = 2f; public bool AttachToParent = false; } // 参数类型 [System.Serializable] public class ParameterEffectConfig : AnimancerEvent.Parameter&lt;EffectConfig&gt; { } /// &lt;summary&gt; /// 技能特效参数示例 /// 使用参数配置特效生成 /// &lt;/summary&gt; public class SkillEffectExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _FireballSkill; [SerializeField] private ClipTransition _IceSpellSkill; [Header(&#34;特效配置&#34;)] [SerializeField] private EffectConfig _FireballEffect; [SerializeField] private EffectConfig _IceEffect; [SerializeField] private Transform _CastPoint; void Awake() { // 注册特效生成事件 _Animancer.Events.AddTo&lt;EffectConfig&gt;(&#34;SpawnEffect&#34;, SpawnEffect); } void SpawnEffect(EffectConfig config) { if (config.EffectPrefab == null) return; // 计算生成位置 Vector3 spawnPos = _CastPoint.position + _CastPoint.TransformDirection(config.LocalOffset); // 生成特效 GameObject effect = Instantiate( config.EffectPrefab, spawnPos, _CastPoint.rotation ); // 是否附加到父物体 if (config.AttachToParent) { effect.transform.SetParent(_CastPoint); } // 设置生命周期 Destroy(effect, config.Lifetime); Debug.Log($&#34;生成特效: {config.EffectPrefab.name}&#34;); } void Update() { if (Input.GetKeyDown(KeyCode.Alpha1)) { _Animancer.Play(_FireballSkill); } else if (Input.GetKeyDown(KeyCode.Alpha2)) { _Animancer.Play(_IceSpellSkill); } } } /* Inspector配置： - FireballSkill: Event=&#34;SpawnEffect&#34;, Parameter=_FireballEffect @ 0.6 - IceSpellSkill: Event=&#34;SpawnEffect&#34;, Parameter=_IceEffect @ 0.5 */示例4：多参数组合#using Animancer; using UnityEngine; // 复合参数配置 [System.Serializable] public class AttackData { public int Damage; public float KnockbackForce; public Vector3 HitDirection; public AudioClip HitSound; public ParticleSystem HitEffect; } // 参数类型 [System.Serializable] public class ParameterAttackData : AnimancerEvent.Parameter&lt;AttackData&gt; { } /// &lt;summary&gt; /// 多参数组合示例 /// 使用复合参数传递多个配置 /// &lt;/summary&gt; public class MultiParameterExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [Header(&#34;攻击配置&#34;)] [SerializeField] private AttackData _LightAttackData; [SerializeField] private AttackData _HeavyAttackData; [SerializeField] private AttackData _SpecialAttackData; [SerializeField] private AudioSource _AudioSource; void Awake() { // 注册复合参数事件 _Animancer.Events.AddTo&lt;AttackData&gt;(&#34;ExecuteAttack&#34;, ExecuteAttack); } void ExecuteAttack(AttackData data) { Debug.Log($&#34;执行攻击:&#34;); Debug.Log($&#34;- 伤害: {data.Damage}&#34;); Debug.Log($&#34;- 击退: {data.KnockbackForce}&#34;); Debug.Log($&#34;- 方向: {data.HitDirection}&#34;); // 播放音效 if (data.HitSound != null) { _AudioSource.PlayOneShot(data.HitSound); } // 播放特效 if (data.HitEffect != null) { data.HitEffect.Play(); } // 执行攻击逻辑 PerformAttackLogic(data); } void PerformAttackLogic(AttackData data) { // 检测敌人 Collider[] enemies = Physics.OverlapSphere(transform.position, 2f); foreach (var enemy in enemies) { if (enemy.CompareTag(&#34;Enemy&#34;)) { // 造成伤害 enemy.GetComponent&lt;Enemy&gt;()?.TakeDamage(data.Damage); // 应用击退 Rigidbody rb = enemy.GetComponent&lt;Rigidbody&gt;(); if (rb != null) { rb.AddForce(data.HitDirection * data.KnockbackForce, ForceMode.Impulse); } } } } }最佳实践#✅ DO（推荐做法）#使用参数避免重复事件名 // ✅ 好：单个事件名，用参数区分 _Animancer.Events.AddTo&lt;FootType&gt;(&#34;Footstep&#34;, OnFootstep); // ❌ 差：多个事件名 _Animancer.Events.Add(&#34;FootstepLeft&#34;, OnFootstepLeft); _Animancer.Events.Add(&#34;FootstepRight&#34;, OnFootstepRight);为值类型使用 ParameterBoxed // ✅ 好：值类型使用ParameterBoxed [System.Serializable] public class ParameterVector3 : AnimancerEvent.ParameterBoxed&lt;Vector3&gt; { }为引用类型使用 Parameter // ✅ 好：引用类型使用Parameter [System.Serializable] public class ParameterAudioSource : AnimancerEvent.Parameter&lt;AudioSource&gt; { }使用配置对象传递多个参数 // ✅ 好：封装配置 public class AttackConfig { public int Damage; public float Range; public AudioClip Sound; }❌ DON&rsquo;T（避免做法）#不要为每个参数值创建事件名 // ❌ 差：难以维护 &#34;FootstepLeft&#34;, &#34;FootstepRight&#34;, &#34;FootstepLeftHeavy&#34;, ...不要混淆参数类型基类 // ❌ 差：Vector3是值类型，应该用ParameterBoxed public class ParameterVector3 : AnimancerEvent.Parameter&lt;Vector3&gt; { } // 错误！不要在参数中存储状态 // ❌ 差：参数应该是数据，不是状态 public class BadParameter { public bool hasTriggered; // 不应该有状态 }FAQ常见问题#Q1: 什么时候应该使用参数？#A:
场景 是否使用参数 多个事件只是参数不同 ✅ 使用 需要传递配置数据 ✅ 使用 事件逻辑完全不同 ❌ 不使用，分开事件 简单的无数据事件 ❌ 不使用 Q2: Parameter 和 ParameterBoxed 有什么区别？#A:
// Parameter: 用于引用类型（class） public class ParameterAudioSource : AnimancerEvent.Parameter&lt;AudioSource&gt; { } // ParameterBoxed: 用于值类型（struct, enum） public class ParameterVector3 : AnimancerEvent.ParameterBoxed&lt;Vector3&gt; { }Q3: 如何在Inspector中设置参数值？#A: 创建参数类型后，会自动在Inspector的事件面板中显示参数字段：
Event: ├─ Name: &#34;Footstep&#34; ├─ Time: 0.3 └─ Parameter: [FootType Dropdown] └─ Left / RightQ4: 可以传递多个参数吗？#A: 不能直接传递多个参数，但可以封装为配置对象：
// ✅ 好：封装多个参数 public class EventData { public int Param1; public string Param2; public Vector3 Param3; } _Animancer.Events.AddTo&lt;EventData&gt;(&#34;Event&#34;, OnEvent);Q5: 参数类型必须标记为 [Serializable] 吗？#A: 如果需要在Inspector中配置，必须标记：
// ✅ 好：可以在Inspector中配置 [System.Serializable] public class ParameterData : AnimancerEvent.Parameter&lt;MyData&gt; { } // ❌ 差：无法在Inspector中配置 public class ParameterData : AnimancerEvent.Parameter&lt;MyData&gt; { }参考资料#📚 相关文档#Animancer Events - Usage Animancer Events - Behaviour Footstep Events 示例 🔗 API 参考#AnimancerEvent.Parameter&lt;T&gt; AnimancerEvent.ParameterBoxed&lt;T&gt; IInvokable 接口 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+（需要 Pro 版本）

Animancer Events - Utilities 官方文档#📋 目录#概述 AnimancerEvent.Current 三个实用工具 Log Current Event Restart Current State Pause At Current Event 代码示例 最佳实践 FAQ常见问题 参考资料 概述#本文档展示了利用 AnimancerEvent.Current 属性在事件触发时访问其详情，实现多种实用行为的代码片段。
🎯 核心概念#&ldquo;AnimancerEvent.Current 属性允许在事件触发时访问事件详情&rdquo;
🔧 委托字段设计#关键设计：&ldquo;方法声明为委托字段而非常规方法，避免创建垃圾回收对象&rdquo;
// ✅ 好：使用委托字段（无GC） public static readonly Action LogEvent = () =&gt; { Debug.Log(AnimancerEvent.Current); }; // ❌ 差：使用常规方法（每次调用分配GC） public static void LogEvent() { Debug.Log(AnimancerEvent.Current); }AnimancerEvent.Current#🎯 访问当前事件#AnimancerEvent.Current 是一个静态属性，在事件回调执行期间可以访问当前触发的事件详情。
📊 可用信息#void OnEvent() { var evt = AnimancerEvent.Current; // 事件信息 Debug.Log($&#34;事件名称: {evt.name}&#34;); Debug.Log($&#34;归一化时间: {evt.normalizedTime}&#34;); Debug.Log($&#34;时间（秒）: {evt.time}&#34;); // 动画状态 var state = evt.state; Debug.Log($&#34;动画名称: {state.Clip.name}&#34;); Debug.Log($&#34;动画速度: {state.Speed}&#34;); Debug.Log($&#34;动画权重: {state.Weight}&#34;); // 事件序列 var sequence = evt.sequence; Debug.Log($&#34;事件总数: {sequence.Count}&#34;); }⚠️ 生命周期#void OnEvent() { // ✅ 可用：在回调函数内 var evt = AnimancerEvent.Current; StartCoroutine(DelayedAccess()); } IEnumerator DelayedAccess() { yield return null; // ❌ 不可用：回调函数外（已过期） var evt = AnimancerEvent.Current; // null 或 旧值 }三个实用工具#📋 工具概览#工具 功能 典型用途 Log Current Event 记录事件详情 调试事件触发 Restart Current State 重启动画 强制循环播放 Pause At Current Event 暂停于事件点 精确控制动画流程 Log Current Event（日志记录事件）#🎯 功能#记录事件触发的详细信息，方便调试和分析。
📝 实现代码#using Animancer; using UnityEngine; public static class AnimancerEventUtilities { /// &lt;summary&gt; /// 日志记录当前事件 /// 委托字段设计避免GC分配 /// &lt;/summary&gt; public static readonly System.Action LogCurrentEvent = () =&gt; { var evt = AnimancerEvent.Current; Debug.Log($&#34;&lt;b&gt;Animancer Event 触发:&lt;/b&gt;\n&#34; + $&#34;- 事件名称: {evt.name}\n&#34; + $&#34;- 归一化时间: {evt.normalizedTime:F3}\n&#34; + $&#34;- 绝对时间: {evt.time:F3}s\n&#34; + $&#34;- 动画: {evt.state.Clip.name}\n&#34; + $&#34;- 状态: {evt.state}\n&#34; + $&#34;- 权重: {evt.state.Weight:F2}&#34;, evt.state.Graph.Component as Object); }; }📚 使用方法#方法1：批量添加到所有事件#using Animancer; using UnityEngine; public class LogEventExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _AttackTransition; void Start() { var state = _Animancer.Play(_AttackTransition); // 为所有事件添加日志回调 foreach (var evt in state.Events) { evt.callback += AnimancerEventUtilities.LogCurrentEvent; } } }方法2：为特定事件添加#void Start() { var state = _Animancer.Play(_AttackTransition); // 只为特定事件添加日志 state.Events.Add(0.5f, AnimancerEventUtilities.LogCurrentEvent); }方法3：组合其他回调#void Start() { var state = _Animancer.Play(_AttackTransition); state.Events.Add(0.5f, () =&gt; { // 先记录日志 AnimancerEventUtilities.LogCurrentEvent(); // 再执行业务逻辑 OnAttackHit(); }); } void OnAttackHit() { Debug.Log(&#34;执行攻击判定&#34;); }🎯 Console高亮#日志中的对象引用可以在Console中直接点击高亮相关GameObject：
Debug.Log(&#34;事件触发&#34;, evt.state.Graph.Component as Object); // ↑ 点击可在Hierarchy中高亮Restart Current State（重启当前状态）#🎯 功能#将动画时间重置为0，强制重新开始播放。
📝 实现代码#public static class AnimancerEventUtilities { /// &lt;summary&gt; /// 重启当前动画状态 /// 将时间重置为0 /// &lt;/summary&gt; public static readonly System.Action RestartCurrentState = () =&gt; { var state = AnimancerEvent.Current.State; state.Time = 0; Debug.Log($&#34;重启动画: {state.Clip.name}&#34;); }; }📚 使用场景#场景1：强制循环播放非循环动画#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 强制循环播放非循环动画 /// &lt;/summary&gt; public class ForceLoopExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; // 非循环动画 void Start() { var state = _Animancer.Play(_AttackClip); state.IsLooping = false; // 在结束事件中重启动画，实现手动循环 state.Events.OnEnd = AnimancerEventUtilities.RestartCurrentState; Debug.Log(&#34;非循环动画将无限循环播放&#34;); } }场景2：条件性重播#public class ConditionalRestartExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _ChargeClip; private bool _isCharging = false; void Start() { var state = _Animancer.Play(_ChargeClip); state.IsLooping = false; // 如果还在蓄力，就重启动画 state.Events.OnEnd = () =&gt; { if (_isCharging) { AnimancerEventUtilities.RestartCurrentState(); } else { _Animancer.Play(_IdleClip); } }; } void Update() { // 按住按钮持续蓄力 _isCharging = Input.GetKey(KeyCode.Space); } [SerializeField] private AnimationClip _IdleClip; }Pause At Current Event（暂停于当前事件）#🎯 功能#在特定事件处暂停动画播放，保持在事件的归一化时间。
🔑 关键特性#&ldquo;停止播放但保持在事件的归一化时间&rdquo;
&ldquo;无需将动画分割为多个片段&rdquo;
&ldquo;支持按事件名称精准触发&rdquo;
📝 实现代码#public static class AnimancerEventUtilities { /// &lt;summary&gt; /// 暂停于当前事件 /// &lt;/summary&gt; public static readonly System.Action PauseAtCurrentEvent = () =&gt; { var evt = AnimancerEvent.Current; var state = evt.State; // 设置时间为事件时间 state.Time = evt.time; // 暂停播放 state.IsPlaying = false; Debug.Log($&#34;暂停于事件: {evt.name} @ {evt.normalizedTime:P0}&#34;); }; /// &lt;summary&gt; /// 按事件名称暂停 /// &lt;/summary&gt; public static System.Action PauseAtEvent(string eventName) { return () =&gt; { var evt = AnimancerEvent.Current; if (evt.name == eventName) { PauseAtCurrentEvent(); } }; } }📚 使用场景#场景1：分段播放动画#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 分段播放动画示例 /// 在特定点暂停，等待输入后继续 /// &lt;/summary&gt; public class PausedAnimationExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _ComboTransition; private AnimancerState _currentState; void Start() { _currentState = _Animancer.Play(_ComboTransition); // 在&#34;ComboWindow&#34;事件处暂停 _currentState.Events.Add(&#34;ComboWindow&#34;, AnimancerEventUtilities.PauseAtEvent(&#34;ComboWindow&#34;)); } void Update() { // 按下按键继续播放 if (Input.GetKeyDown(KeyCode.Mouse0)) { if (!_currentState.IsPlaying) { Debug.Log(&#34;继续播放动画&#34;); _currentState.IsPlaying = true; } } } }场景2：QTE系统#using Animancer; using UnityEngine; using UnityEngine.UI; /// &lt;summary&gt; /// QTE（Quick Time Event）系统 /// 在特定点暂停，等待玩家输入 /// &lt;/summary&gt; public class QTESystem : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _FinisherTransition; [SerializeField] private Text _QTEPrompt; private AnimancerState _currentState; private bool _waitingForInput = false; void Start() { _QTEPrompt.gameObject.SetActive(false); _currentState = _Animancer.Play(_FinisherTransition); // 在QTE点暂停 _currentState.Events.Add(&#34;QTE&#34;, OnQTEPoint); } void OnQTEPoint() { var evt = AnimancerEvent.Current; var state = evt.State; // 暂停动画 state.Time = evt.time; state.IsPlaying = false; // 显示提示 _QTEPrompt.text = &#34;按下 [Space] 完成终结技！&#34;; _QTEPrompt.gameObject.SetActive(true); _waitingForInput = true; // 启动超时检测 StartCoroutine(QTETimeout()); } void Update() { if (_waitingForInput &amp;&amp; Input.GetKeyDown(KeyCode.Space)) { OnQTESuccess(); } } void OnQTESuccess() { _waitingForInput = false; _QTEPrompt.gameObject.SetActive(false); Debug.Log(&#34;QTE成功！&#34;); // 继续播放动画 _currentState.IsPlaying = true; StopAllCoroutines(); } System.Collections.IEnumerator QTETimeout() { yield return new WaitForSeconds(1.5f); if (_waitingForInput) { _waitingForInput = false; _QTEPrompt.gameObject.SetActive(false); Debug.Log(&#34;QTE失败！&#34;); // 播放失败动画 _Animancer.Play(_FailClip); } } [SerializeField] private AnimationClip _FailClip; }场景3：教学系统#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 教学系统 /// 在关键步骤暂停，显示提示 /// &lt;/summary&gt; public class TutorialSystem : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _TutorialAnimation; private string[] _tutorialTexts = { &#34;步骤1: 移动角色...&#34;, &#34;步骤2: 瞄准目标...&#34;, &#34;步骤3: 按下攻击键...&#34; }; private int _currentStep = 0; void Start() { var state = _Animancer.Play(_TutorialAnimation); // 在多个点暂停 state.Events.Add(&#34;Step1&#34;, () =&gt; OnTutorialStep(0)); state.Events.Add(&#34;Step2&#34;, () =&gt; OnTutorialStep(1)); state.Events.Add(&#34;Step3&#34;, () =&gt; OnTutorialStep(2)); } void OnTutorialStep(int stepIndex) { AnimancerEventUtilities.PauseAtCurrentEvent(); _currentStep = stepIndex; Debug.Log(_tutorialTexts[stepIndex]); // 显示UI提示 ShowTutorialPrompt(_tutorialTexts[stepIndex]); } void Update() { // 按任意键继续 if (Input.anyKeyDown) { ContinueTutorial(); } } void ContinueTutorial() { var state = _Animancer.States.Current; if (state != null &amp;&amp; !state.IsPlaying) { Debug.Log(&#34;继续教学...&#34;); state.IsPlaying = true; HideTutorialPrompt(); } } void ShowTutorialPrompt(string text) { /* UI逻辑 */ } void HideTutorialPrompt() { /* UI逻辑 */ } }代码示例#示例1：整合三个工具#using Animancer; using UnityEngine; /// &lt;summary&gt; /// 整合所有事件工具的完整示例 /// &lt;/summary&gt; public class EventUtilitiesIntegration : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _ComboAttack; void Awake() { var state = _Animancer.Play(_ComboAttack); // 1. 为所有事件添加日志 foreach (var evt in state.Events) { evt.callback += AnimancerEventUtilities.LogCurrentEvent; } // 2. 在连击窗口暂停 state.Events.Add(&#34;ComboWindow&#34;, AnimancerEventUtilities.PauseAtEvent(&#34;ComboWindow&#34;)); // 3. 根据条件重启或结束 state.Events.OnEnd = () =&gt; { if (Input.GetKey(KeyCode.Mouse0)) { // 玩家还在按攻击键，重启动画 AnimancerEventUtilities.RestartCurrentState(); } else { // 返回Idle _Animancer.Play(_IdleClip); } }; } [SerializeField] private AnimationClip _IdleClip; }示例2：自定义事件工具#using Animancer; using UnityEngine; public static class CustomEventUtilities { /// &lt;summary&gt; /// 减速播放当前动画 /// &lt;/summary&gt; public static readonly System.Action SlowDown = () =&gt; { var state = AnimancerEvent.Current.State; state.Speed *= 0.5f; Debug.Log($&#34;动画减速: {state.Speed}x&#34;); }; /// &lt;summary&gt; /// 加速播放当前动画 /// &lt;/summary&gt; public static readonly System.Action SpeedUp = () =&gt; { var state = AnimancerEvent.Current.State; state.Speed *= 2f; Debug.Log($&#34;动画加速: {state.Speed}x&#34;); }; /// &lt;summary&gt; /// 播放音效 /// &lt;/summary&gt; public static System.Action PlaySound(AudioClip clip, AudioSource source) { return () =&gt; { if (clip != null &amp;&amp; source != null) { source.PlayOneShot(clip); Debug.Log($&#34;播放音效: {clip.name}&#34;); } }; } /// &lt;summary&gt; /// 生成粒子特效 /// &lt;/summary&gt; public static System.Action SpawnParticle(ParticleSystem prefab, Transform spawnPoint) { return () =&gt; { if (prefab != null &amp;&amp; spawnPoint != null) { var particle = Object.Instantiate(prefab, spawnPoint.position, spawnPoint.rotation); particle.Play(); Debug.Log($&#34;生成特效: {prefab.name}&#34;); } }; } }最佳实践#✅ DO（推荐做法）#使用委托字段避免GC // ✅ 好：委托字段 public static readonly Action MyUtility = () =&gt; { };检查AnimancerEvent.Current的有效性 // ✅ 好：检查生命周期 void OnEvent() { var evt = AnimancerEvent.Current; if (evt != null) { // 使用evt } }组合多个工具 // ✅ 好：链式调用 state.Events.Add(0.5f, () =&gt; { AnimancerEventUtilities.LogCurrentEvent(); OnAttackHit(); });为调试添加日志工具 // ✅ 好：开发阶段启用日志 #if UNITY_EDITOR foreach (var evt in state.Events) { evt.callback += AnimancerEventUtilities.LogCurrentEvent; } #endif❌ DON&rsquo;T（避免做法）#不要在回调外使用AnimancerEvent.Current // ❌ 差：生命周期外使用 IEnumerator DelayedUse() { yield return null; var evt = AnimancerEvent.Current; // 无效 }不要使用常规方法（产生GC） // ❌ 差：每次调用分配GC public static void MyUtility() { }不要忘记恢复播放状态 // ❌ 差：暂停后忘记恢复 state.IsPlaying = false; // 忘记在某个时机设置 state.IsPlaying = true;FAQ常见问题#Q1: 为什么要使用委托字段而不是方法？#A: 性能优化，避免GC分配：
// 委托字段：只分配一次 public static readonly Action LogEvent = () =&gt; { }; // 常规方法：每次创建新的委托对象 public static void LogEvent() { } // 使用时： state.Events.Add(0.5f, LogEvent); // 字段：无GC state.Events.Add(0.5f, () =&gt; LogEvent()); // 方法：有GCQ2: AnimancerEvent.Current什么时候可用？#A: 仅在事件回调执行期间：
事件触发 → AnimancerEvent.Current 有效 ↓ 回调执行完毕 → AnimancerEvent.Current 无效Q3: 如何创建自己的事件工具？#A: 遵循委托字段模式：
public static class MyUtilities { public static readonly Action MyTool = () =&gt; { var evt = AnimancerEvent.Current; // 使用evt实现功能 }; }Q4: 暂停事件后如何恢复？#A: 手动设置IsPlaying：
// 暂停 state.IsPlaying = false; // 恢复 state.IsPlaying = true;Q5: 可以在暂停状态下修改动画吗？#A: 可以：
// 暂停后可以修改 state.IsPlaying = false; state.Time = 1.0f; // 修改时间 state.Speed = 0.5f; // 修改速度 state.Weight = 0.5f; // 修改权重 // 然后恢复播放 state.IsPlaying = true;参考资料#📚 相关文档#Animancer Events - Behaviour Animancer Events - Usage AnimancerState API 🔗 API 参考#AnimancerEvent.Current AnimancerEvent.State AnimancerState.Time AnimancerState.IsPlaying 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer Fading Modes 官方文档#原文地址：https://kybernetik.com.au/animancer/docs/manual/blending/fading/modes/ 抓取日期：2025-01-24
概述 (Overview)#FadeMode（淡入模式） 是 Animancer 中控制淡入淡出行为的重要参数。它决定了淡入持续时间如何被解释和应用。
Play 方法接受一个可选的 FadeMode 参数，如果不指定则默认使用 FadeMode.FixedSpeed。
基础用法 (Basic Usage)#// 方式1：使用默认模式（FixedSpeed） _Animancer.Play(clip, 0.25f); // 方式2：显式指定模式（等价于方式1） _Animancer.Play(clip, 0.25f, FadeMode.FixedSpeed); // 方式3：使用其他模式 _Animancer.Play(clip, 0.2f, FadeMode.NormalizedSpeed);淡入模式分类 (Fade Mode Categories)#1. Fixed Modes（固定模式）#定义：淡入持续时间独立于动画长度。
特点：
✅ 时长固定，不受动画长度影响 ⚠️ 如果淡入时长超过动画长度，可能导致淡入未完成 💡 适合淡入时长已知且稳定的场景 示例：
// 固定 0.25 秒淡入，无论动画长度 _Animancer.Play(clip, 0.25f, FadeMode.FixedSpeed); // 动画长度 = 0.5 秒 // 实际淡入时长 = 0.25 秒 ✅ // 动画长度 = 0.1 秒 // 实际淡入时长 = 0.25 秒 ⚠️（超过动画长度！）2. Normalized Modes（归一化模式）#定义：淡入持续时间基于动画长度计算。
特点：
✅ 自动适应动画长度 ✅ 确保淡入在动画播放期间完成 💡 适合不同长度动画使用统一比例的场景 时长范围：通常在 0-1 之间（代表动画长度的百分比）
示例：
// 淡入时长 = 动画长度 × 0.2（20%） _Animancer.Play(clip, 0.2f, FadeMode.NormalizedSpeed); // 动画长度 = 2 秒 // 实际淡入时长 = 2 × 0.2 = 0.4 秒 ✅ // 动画长度 = 0.5 秒 // 实际淡入时长 = 0.5 × 0.2 = 0.1 秒 ✅主要淡入模式详解 (Main Fade Modes)#1. FadeMode.FixedSpeed（默认）#定义：固定速度淡入，时长不受动画长度影响。
公式：
实际淡入时长 = 指定的 fadeDuration（秒）代码示例：
// 固定 0.3 秒淡入 _Animancer.Play(clip, 0.3f, FadeMode.FixedSpeed); // 或省略模式参数（默认） _Animancer.Play(clip, 0.3f);适用场景：
✅ 已知合适的淡入时长 ✅ 所有动画长度相似 ✅ 需要统一的淡入体验 注意事项：
// ⚠️ 问题：淡入时长可能超过动画长度 AnimationClip shortClip; // 长度 0.2 秒 _Animancer.Play(shortClip, 0.5f, FadeMode.FixedSpeed); // 淡入时长 0.5 秒 &gt; 动画长度 0.2 秒 // 结果：动画播放完毕，淡入仍未完成2. FadeMode.NormalizedSpeed#定义：淡入时长基于新动画的长度计算。
公式：
实际淡入时长 = 新动画长度 × fadeDuration代码示例：
// 淡入时长 = 新动画长度的 20% _Animancer.Play(clip, 0.2f, FadeMode.NormalizedSpeed); // 示例1：新动画长度 = 3 秒 // 实际淡入时长 = 3 × 0.2 = 0.6 秒 // 示例2：新动画长度 = 1 秒 // 实际淡入时长 = 1 × 0.2 = 0.2 秒适用场景：
✅ 动画长度差异较大 ✅ 希望淡入时长与动画长度成比例 ✅ 长动画使用长淡入，短动画使用短淡入 实际应用：
public class NormalizedSpeedExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _ShortClip; // 1 秒 [SerializeField] private AnimationClip _LongClip; // 5 秒 void PlayWithProportionalFade() { // 两个动画都使用 15% 的淡入时长 float fadeRatio = 0.15f; // 短动画：淡入 0.15 秒（1 × 0.15） _Animancer.Play(_ShortClip, fadeRatio, FadeMode.NormalizedSpeed); // 长动画：淡入 0.75 秒（5 × 0.15） _Animancer.Play(_LongClip, fadeRatio, FadeMode.NormalizedSpeed); } }3. FadeMode.NormalizedDuration#定义：淡入时长基于新动画的长度和速度计算。
公式：
实际淡入时长 = (新动画长度 × fadeDuration) / 播放速度代码示例：
// 淡入时长 = 新动画长度的 10% ÷ 播放速度 _Animancer.Play(clip, 0.1f, FadeMode.NormalizedDuration); // 示例1：新动画长度 = 2 秒，速度 = 1x // 实际淡入时长 = (2 × 0.1) / 1 = 0.2 秒 // 示例2：新动画长度 = 2 秒，速度 = 2x（加速） // 实际淡入时长 = (2 × 0.1) / 2 = 0.1 秒 // 示例3：新动画长度 = 2 秒，速度 = 0.5x（减速） // 实际淡入时长 = (2 × 0.1) / 0.5 = 0.4 秒适用场景：
✅ 动画播放速度经常变化 ✅ 希望淡入时长适应速度变化 ✅ 慢动作或快动作效果 实际应用：
public class NormalizedDurationExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _AttackAnimation; void PlayAttackWithSpeed(float speedMultiplier) { _AttackAnimation.Speed = speedMultiplier; // 淡入时长会根据速度自动调整 _Animancer.Play(_AttackAnimation, 0.1f, FadeMode.NormalizedDuration); // 速度 = 2x（快速攻击） // 淡入时长会减半 // 速度 = 0.5x（慢动作攻击） // 淡入时长会加倍 } }4. FadeMode.FromStart#定义：从头开始重新播放动画，通过克隆状态实现新旧动画的交叉淡入淡出。
工作原理：
旧状态：|=============&gt; (从当前时间继续播放并淡出) 新状态：|=============&gt; (从 0 开始播放并淡入) ↑ 创建克隆代码示例：
// 从头开始播放，创建克隆状态 _Animancer.Play(clip, 0.25f, FadeMode.FromStart);重要特性：
克隆创建条件：
// 当现有状态的权重超过阈值时才克隆 if (existingState.Weight &gt; AnimancerLayer.WeightlessThreshold) { // 创建克隆（默认阈值 = 0.1） }最大克隆数量：
// 默认最多 3 个克隆 AnimancerLayer.MaxCloneCount = 3; // 超过限制时，复用权重最低的克隆非 ClipState 警告：
// 克隆复杂状态（如 Mixer）会生成警告 // OptionalWarning.CloneComplexState适用场景：
✅ 需要从头重新播放动画 ✅ 当前动画播放到一半，但需要重新开始 ✅ 连续触发相同动画（如连续攻击） 实际应用：
public class FromStartExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _PunchClip; void OnPunchInput() { // 每次按下都从头开始播放攻击动画 // 即使上一次攻击还没播放完 _Animancer.Play(_PunchClip, 0.15f, FadeMode.FromStart); } }克隆管理示例：
public class CloneManagementExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; void Start() { // 调整克隆阈值（更敏感） _Animancer.Layers[0].WeightlessThreshold = 0.05f; // 调整最大克隆数量 _Animancer.Layers[0].MaxCloneCount = 5; } void PlayFromStart(AnimationClip clip) { _Animancer.Play(clip, 0.2f, FadeMode.FromStart); // 检查克隆数量 int cloneCount = 0; foreach (var state in _Animancer.States) { if (state.Clip == clip) { cloneCount++; } } Debug.Log($&#34;克隆数量: {cloneCount}&#34;); } }Transition 默认模式 (Transition Defaults)#Transition 的默认 FadeMode 取决于 &ldquo;Start Time&rdquo; 切换按钮的设置：
配置对照表#Start Time 设置 默认 FadeMode 行为说明 启用（Enabled） FadeMode.FromStart 总是从指定时间开始播放 禁用（Disabled） FadeMode.FixedSpeed 从当前播放位置继续 Inspector 配置#TransitionAsset Inspector: ┌─────────────────────────┐ │ Start Time: ☑ Enabled │ ← 勾选 │ → Default: FromStart │ └─────────────────────────┘ ┌─────────────────────────┐ │ Start Time: ☐ Disabled │ ← 未勾选 │ → Default: FixedSpeed │ └─────────────────────────┘代码覆盖默认值#// 即使 Transition 默认是 FromStart，也可以覆盖 _Animancer.Play(_Transition, fadeDuration: 0.3f, FadeMode.FixedSpeed);模式对比表 (Mode Comparison Table)#FadeMode 时长计算 受速度影响 克隆状态 适用场景 FixedSpeed 固定值 ❌ ❌ 标准过渡 NormalizedSpeed 动画长度 × 比例 ❌ ❌ 不同长度动画 NormalizedDuration 动画长度 × 比例 / 速度 ✅ ❌ 速度变化场景 FromStart 固定值 ❌ ✅ 从头重播 代码示例集合#示例1：对比不同模式#using Animancer; using UnityEngine; public class FadeModeComparisonExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _TestClip; // 长度 2 秒 void TestFixedSpeed() { // 固定 0.5 秒淡入 _Animancer.Play(_TestClip, 0.5f, FadeMode.FixedSpeed); Debug.Log(&#34;淡入时长: 0.5 秒&#34;); } void TestNormalizedSpeed() { // 淡入时长 = 2 × 0.25 = 0.5 秒 _Animancer.Play(_TestClip, 0.25f, FadeMode.NormalizedSpeed); Debug.Log(&#34;淡入时长: &#34; + (2 * 0.25f) + &#34; 秒&#34;); } void TestNormalizedDuration() { // 假设速度 = 1x // 淡入时长 = (2 × 0.25) / 1 = 0.5 秒 _Animancer.Play(_TestClip, 0.25f, FadeMode.NormalizedDuration); Debug.Log(&#34;淡入时长: &#34; + ((2 * 0.25f) / 1) + &#34; 秒&#34;); } void TestFromStart() { // 从头开始，淡入 0.5 秒 _Animancer.Play(_TestClip, 0.5f, FadeMode.FromStart); Debug.Log(&#34;从头开始播放，淡入时长: 0.5 秒&#34;); } }示例2：动态选择模式#using Animancer; using UnityEngine; public class DynamicModeSelectionExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _Clip; void PlayWithAdaptiveMode(bool shouldRestart, float speed) { float fadeDuration = 0.25f; FadeMode mode; if (shouldRestart) { // 需要重新开始 mode = FadeMode.FromStart; } else if (speed != 1.0f) { // 速度变化，使用 NormalizedDuration mode = FadeMode.NormalizedDuration; } else { // 标准情况 mode = FadeMode.FixedSpeed; } _Animancer.Play(_Clip, fadeDuration, mode); Debug.Log($&#34;使用模式: {mode}&#34;); } }示例3：FromStart 连续攻击#using Animancer; using UnityEngine; public class ContinuousAttackExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip _AttackClip; private int _attackCount = 0; void Update() { if (Input.GetMouseButtonDown(0)) { PerformAttack(); } } void PerformAttack() { _attackCount++; // 每次攻击都从头开始，即使上次还没播完 _Animancer.Play(_AttackClip, 0.1f, FadeMode.FromStart); Debug.Log($&#34;攻击 #{_attackCount} - 从头开始播放&#34;); } }示例4：基于动画长度的自适应淡入#using Animancer; using UnityEngine; public class AdaptiveFadeExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private AnimationClip[] _Clips; [SerializeField, Range(0f, 1f)] private float _fadeRatio = 0.2f; // 20% void PlayRandomClipWithAdaptiveFade() { AnimationClip randomClip = _Clips[Random.Range(0, _Clips.Length)]; // 使用 NormalizedSpeed 确保所有动画都使用相同比例的淡入 _Animancer.Play(randomClip, _fadeRatio, FadeMode.NormalizedSpeed); float actualFadeDuration = randomClip.length * _fadeRatio; Debug.Log($&#34;动画: {randomClip.name}, 长度: {randomClip.length:F2}s, 淡入: {actualFadeDuration:F2}s&#34;); } }示例5：速度变化场景#using Animancer; using UnityEngine; public class SpeedBasedFadeExample : MonoBehaviour { [SerializeField] private AnimancerComponent _Animancer; [SerializeField] private ClipTransition _Animation; void PlayWithSpeed(float speedMultiplier) { _Animation.Speed = speedMultiplier; // 使用 NormalizedDuration 适应速度变化 _Animancer.Play(_Animation, 0.15f, FadeMode.NormalizedDuration); float clipLength = _Animation.Clip.length; float actualFade = (clipLength * 0.15f) / speedMultiplier; Debug.Log($&#34;速度: {speedMultiplier}x, 淡入时长: {actualFade:F2}s&#34;); } // 测试方法 [ContextMenu(&#34;Normal Speed&#34;)] void NormalSpeed() =&gt; PlayWithSpeed(1.0f); // 标准淡入 [ContextMenu(&#34;Fast Speed&#34;)] void FastSpeed() =&gt; PlayWithSpeed(2.0f); // 淡入减半 [ContextMenu(&#34;Slow Speed&#34;)] void SlowSpeed() =&gt; PlayWithSpeed(0.5f); // 淡入加倍 }最佳实践建议#1. 选择合适的模式#// ✅ 推荐：根据场景选择模式 FadeMode GetAppropriateFadeMode(AnimationType type, float speed) { switch (type) { case AnimationType.QuickAction: return FadeMode.FixedSpeed; // 固定快速过渡 case AnimationType.Movement: if (speed != 1.0f) return FadeMode.NormalizedDuration; // 速度变化 else return FadeMode.NormalizedSpeed; // 标准移动 case AnimationType.Restart: return FadeMode.FromStart; // 需要重新开始 default: return FadeMode.FixedSpeed; } }2. 避免常见错误#// ❌ 错误：FixedSpeed 时长超过动画长度 AnimationClip shortClip; // 长度 0.3 秒 _Animancer.Play(shortClip, 1.0f, FadeMode.FixedSpeed); // 淡入时长 1 秒 &gt; 动画长度 0.3 秒 // ✅ 正确：使用 NormalizedSpeed _Animancer.Play(shortClip, 0.3f, FadeMode.NormalizedSpeed); // 淡入时长 = 0.3 × 0.3 = 0.09 秒 ✅3. 管理 FromStart 克隆#// ✅ 监控克隆数量 void MonitorClones(AnimationClip targetClip) { int cloneCount = 0; foreach (var state in _Animancer.States) { if (state.Clip == targetClip) { cloneCount++; } } if (cloneCount &gt; AnimancerLayer.MaxCloneCount) { Debug.LogWarning($&#34;克隆数量过多: {cloneCount}&#34;); } } // ✅ 调整克隆限制 _Animancer.Layers[0].MaxCloneCount = 5; // 增加限制4. Normalized 模式的时长范围#// ✅ 推荐：Normalized 模式使用 0-1 范围 _Animancer.Play(clip, 0.25f, FadeMode.NormalizedSpeed); // 25% // ❌ 不推荐：超过 1 会导致淡入时长过长 _Animancer.Play(clip, 2.0f, FadeMode.NormalizedSpeed); // 200%（过长）常见问题 FAQ#Q1: 什么时候应该使用 NormalizedSpeed 而不是 FixedSpeed？#A: 当动画长度差异较大时使用 NormalizedSpeed：
// 场景：有短动画（0.5秒）和长动画（5秒） // ❌ FixedSpeed：短动画淡入过长 _Animancer.Play(shortClip, 0.5f, FadeMode.FixedSpeed); // 淡入 = 动画长度 // ✅ NormalizedSpeed：比例一致 _Animancer.Play(shortClip, 0.2f, FadeMode.NormalizedSpeed); // 淡入 0.1s _Animancer.Play(longClip, 0.2f, FadeMode.NormalizedSpeed); // 淡入 1.0sQ2: FromStart 模式为什么需要克隆状态？#A: 因为需要同时播放两个相同动画的不同时间点：
旧状态：|====时间2.5s====&gt; 继续播放并淡出 新状态：|====时间0.0s====&gt; 从头开始并淡入 ↑ 必须使用两个独立的状态实例Q3: 克隆复杂状态会有什么问题？#A: 克隆 Mixer 或 Controller 等复杂状态会：
增加内存使用 可能导致状态不同步 触发 OptionalWarning.CloneComplexState 警告 建议：
// ❌ 避免对 Mixer 使用 FromStart _Animancer.Play(_MixerTransition, 0.25f, FadeMode.FromStart); // ✅ 对 ClipTransition 使用 FromStart _Animancer.Play(_ClipTransition, 0.25f, FadeMode.FromStart);Q4: NormalizedDuration 和 NormalizedSpeed 有什么区别？#A:
特性 NormalizedSpeed NormalizedDuration 公式 长度 × 比例 (长度 × 比例) / 速度 受速度影响 ❌ ✅ 适用场景 标准动画 速度变化动画 示例：
// 动画长度 2 秒，速度 2x，比例 0.2 // NormalizedSpeed: 2 × 0.2 = 0.4 秒 // NormalizedDuration: (2 × 0.2) / 2 = 0.2 秒Q5: 如何避免淡入时长超过动画长度？#A:
// 方法1：使用 NormalizedSpeed _Animancer.Play(clip, 0.3f, FadeMode.NormalizedSpeed); // 最多 30% 长度 // 方法2：动态计算 float safeFadeDuration = Mathf.Min(clip.length * 0.5f, 0.25f); _Animancer.Play(clip, safeFadeDuration, FadeMode.FixedSpeed); // 方法3：检查并警告 void SafePlay(AnimationClip clip, float fadeDuration) { if (fadeDuration &gt; clip.length) { Debug.LogWarning($&#34;淡入时长 {fadeDuration} 超过动画长度 {clip.length}&#34;); fadeDuration = clip.length * 0.5f; } _Animancer.Play(clip, fadeDuration); }Q6: 如何在 Inspector 中设置默认 FadeMode？#A: 通过 Transition 的 &ldquo;Start Time&rdquo; 设置：
Inspector: ┌─────────────────────────┐ │ ClipTransition │ │ ├─ Clip: [...] │ │ ├─ Fade Duration: 0.25 │ │ └─ Start Time: ☑ │ ← 勾选 = FromStart └─────────────────────────┘代码中可以覆盖：
// 即使默认是 FromStart，也可以覆盖 _Animancer.Play(_Transition, 0.3f, FadeMode.FixedSpeed);总结#核心要点#四种主要模式
FixedSpeed：固定时长，标准模式 NormalizedSpeed：基于动画长度 NormalizedDuration：考虑播放速度 FromStart：克隆状态，从头开始 选择策略
标准场景：FixedSpeed 不同长度动画：NormalizedSpeed 速度变化：NormalizedDuration 重新开始：FromStart Normalized 模式优势
自动适应动画长度 避免淡入超出动画 保持一致的视觉比例 FromStart 注意事项
会创建状态克隆 有最大克隆数量限制 避免克隆复杂状态 下一步学习#📖 深入学习 Custom Easing 实现非线性淡入 🎨 探索 Sequences 组合多个动画 📚 了解克隆状态的内存管理 🔍 查看实际项目中的模式选择策略 文档抓取日期：2025-01-24 原文地址：https://kybernetik.com.au/animancer/docs/manual/blending/fading/modes/ Animancer 版本：7.0+ 适用项目：animator-third-person-controller (ShooterTPP)

Animancer FSM - Input Buffer 官方文档#📋 目录#概述 核心概念 使用步骤 代码示例 重要限制 参考资料 概述#Input Buffer（输入缓冲） 允许状态机在无法立即转换时将状态变更请求加入队列，并在指定时间内重试转换。
🎯 典型应用场景#&ldquo;如果玩家正在攻击并再次按下攻击键，你可能希望当前动画先完成，然后只要输入没有发生太久之前，就开始连击中的下一次攻击&rdquo;
核心概念#🔄 工作流程#玩家输入攻击 ↓ 当前状态：Attack1（无法退出） ↓ Buffer(Attack2, 0.5秒) ← 缓冲输入 ↓ 每帧 Update() ↓ Attack1完成 → TrySetState(Attack2) ✅ 成功！📊 Buffer vs 直接切换#方式 行为 结果 TrySetState 立即尝试切换 失败则丢弃输入 Buffer 缓冲输入并重试 在超时前持续尝试 使用步骤#步骤1：创建 InputBuffer#using Animancer.FSM; using UnityEngine; public class CombatController : MonoBehaviour { private StateMachine&lt;IState&gt; _stateMachine; private StateMachine&lt;IState&gt;.InputBuffer _inputBuffer; void Awake() { _stateMachine = new StateMachine&lt;IState&gt;(); // 创建InputBuffer _inputBuffer = new StateMachine&lt;IState&gt;.InputBuffer(_stateMachine); } }步骤2：缓冲输入#void Update() { if (Input.GetKeyDown(KeyCode.Mouse0)) { // 使用Buffer代替TrySetState // 参数：状态，超时时间（秒） _inputBuffer.Buffer(_attackState, 0.5f); } }步骤3：每帧更新#void Update() { // 每帧调用Update重试缓冲的状态 _inputBuffer.Update(); // 处理输入... }代码示例#示例1：基础连击系统#using Animancer; using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 使用InputBuffer实现连击系统 /// &lt;/summary&gt; public class ComboSystem : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; private StateMachine&lt;AttackState&gt; _stateMachine; private StateMachine&lt;AttackState&gt;.InputBuffer _inputBuffer; private IdleState _idle; private Attack1State _attack1; private Attack2State _attack2; private Attack3State _attack3; [Header(&#34;缓冲设置&#34;)] [SerializeField] private float _bufferTimeout = 0.5f; // 输入缓冲时间 void Awake() { // 初始化状态机 _stateMachine = new StateMachine&lt;AttackState&gt;(); _inputBuffer = new StateMachine&lt;AttackState&gt;.InputBuffer(_stateMachine); // 创建状态 _idle = new IdleState(this); _attack1 = new Attack1State(this); _attack2 = new Attack2State(this); _attack3 = new Attack3State(this); _stateMachine.TrySetState(_idle); } void Update() { // 每帧更新InputBuffer _inputBuffer.Update(); // 处理攻击输入 if (Input.GetKeyDown(KeyCode.Mouse0)) { HandleAttackInput(); } } void HandleAttackInput() { var current = _stateMachine.CurrentState; if (current == _idle) { // 从Idle直接进入Attack1 _stateMachine.TrySetState(_attack1); } else if (current == _attack1) { // 缓冲Attack2 _inputBuffer.Buffer(_attack2, _bufferTimeout); Debug.Log(&#34;缓冲Attack2输入&#34;); } else if (current == _attack2) { // 缓冲Attack3 _inputBuffer.Buffer(_attack3, _bufferTimeout); Debug.Log(&#34;缓冲Attack3输入&#34;); } } // 状态基类 public abstract class AttackState : IState { protected ComboSystem Controller; protected bool _attackFinished; public AttackState(ComboSystem controller) { Controller = controller; } public virtual bool CanEnterState =&gt; true; // 攻击未完成不能退出 public bool CanExitState =&gt; _attackFinished; public abstract void OnEnterState(); public virtual void OnExitState() { _attackFinished = false; } } // Idle状态 public class IdleState : AttackState { public IdleState(ComboSystem controller) : base(controller) { } public override void OnEnterState() { Debug.Log(&#34;→ Idle&#34;); Controller._animancer.Play(Controller._idleClip); } } // Attack1状态 public class Attack1State : AttackState { public Attack1State(ComboSystem controller) : base(controller) { } public override void OnEnterState() { Debug.Log(&#34;→ Attack1&#34;); _attackFinished = false; var state = Controller._animancer.Play(Controller._attack1Clip); state.Events.OnEnd = () =&gt; { _attackFinished = true; Controller._stateMachine.TrySetState(Controller._idle); }; } } // Attack2状态 public class Attack2State : AttackState { public Attack2State(ComboSystem controller) : base(controller) { } public override void OnEnterState() { Debug.Log(&#34;→ Attack2 (从缓冲进入)&#34;); _attackFinished = false; var state = Controller._animancer.Play(Controller._attack2Clip); state.Events.OnEnd = () =&gt; { _attackFinished = true; Controller._stateMachine.TrySetState(Controller._idle); }; } } // Attack3状态 public class Attack3State : AttackState { public Attack3State(ComboSystem controller) : base(controller) { } public override void OnEnterState() { Debug.Log(&#34;→ Attack3 (从缓冲进入)&#34;); _attackFinished = false; var state = Controller._animancer.Play(Controller._attack3Clip); state.Events.OnEnd = () =&gt; { _attackFinished = true; Controller._stateMachine.TrySetState(Controller._idle); }; } } [SerializeField] private AnimationClip _idleClip; [SerializeField] private AnimationClip _attack1Clip; [SerializeField] private AnimationClip _attack2Clip; [SerializeField] private AnimationClip _attack3Clip; }示例2：带缓冲的跳跃系统#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 使用InputBuffer的跳跃系统 /// 允许在空中时缓冲跳跃输入 /// &lt;/summary&gt; public class JumpSystem : MonoBehaviour { private StateMachine&lt;IState&gt; _stateMachine; private StateMachine&lt;IState&gt;.InputBuffer _inputBuffer; private GroundedState _grounded; private JumpState _jump; [SerializeField] private float _jumpBufferTime = 0.2f; void Awake() { _stateMachine = new StateMachine&lt;IState&gt;(); _inputBuffer = new StateMachine&lt;IState&gt;.InputBuffer(_stateMachine); _grounded = new GroundedState(); _jump = new JumpState(); _stateMachine.TrySetState(_grounded); } void Update() { _inputBuffer.Update(); // 跳跃输入 if (Input.GetKeyDown(KeyCode.Space)) { // 缓冲跳跃输入 // 如果在空中，落地后会自动执行跳跃 _inputBuffer.Buffer(_jump, _jumpBufferTime); Debug.Log(&#34;缓冲跳跃输入&#34;); } } // Grounded状态 public class GroundedState : IState { public bool CanEnterState =&gt; IsGrounded(); public bool CanExitState =&gt; true; public void OnEnterState() { Debug.Log(&#34;落地&#34;); } public void OnExitState() { } bool IsGrounded() { // 实际项目中的地面检测逻辑 return Physics.Raycast( transform.position, Vector3.down, 1.1f ); } } // Jump状态 public class JumpState : IState { public bool CanEnterState =&gt; true; public bool CanExitState =&gt; true; public void OnEnterState() { Debug.Log(&#34;跳跃！&#34;); // 应用跳跃力 } public void OnExitState() { } } }示例3：检查缓冲状态#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 检查和清除缓冲状态 /// &lt;/summary&gt; public class BufferInspection : MonoBehaviour { private StateMachine&lt;IState&gt; _stateMachine; private StateMachine&lt;IState&gt;.InputBuffer _inputBuffer; void Update() { _inputBuffer.Update(); // 检查是否有缓冲的状态 if (_inputBuffer.IsActive) { Debug.Log($&#34;缓冲中: {_inputBuffer.State}&#34;); Debug.Log($&#34;剩余时间: {_inputBuffer.TimeLeft}秒&#34;); } // 取消缓冲 if (Input.GetKeyDown(KeyCode.Escape)) { _inputBuffer.Clear(); Debug.Log(&#34;清除输入缓冲&#34;); } } }重要限制#⚠️ 单一缓冲限制#&ldquo;系统设计上一次只处理一个缓冲状态。如果在缓冲状态执行前发生多个输入，只保留最近的输入。&rdquo;
// 快速连续输入 _inputBuffer.Buffer(attack1, 0.5f); // 缓冲Attack1 _inputBuffer.Buffer(attack2, 0.5f); // 覆盖为Attack2 _inputBuffer.Buffer(attack3, 0.5f); // 覆盖为Attack3 // 最终只会执行Attack3💡 解决方案：序列缓冲#如果需要顺序执行多个命令，可以创建 InputSequenceBuffer 变体：
/// &lt;summary&gt; /// 输入序列缓冲（自定义实现） /// 管理一个状态列表 /// &lt;/summary&gt; public class InputSequenceBuffer { private Queue&lt;IState&gt; _bufferedStates = new Queue&lt;IState&gt;(); private StateMachine&lt;IState&gt; _stateMachine; private float _timeout; public InputSequenceBuffer(StateMachine&lt;IState&gt; stateMachine) { _stateMachine = stateMachine; } public void Buffer(IState state, float timeout) { _bufferedStates.Enqueue(state); _timeout = timeout; } public void Update() { if (_bufferedStates.Count == 0) return; _timeout -= Time.deltaTime; if (_timeout &lt;= 0) { _bufferedStates.Clear(); return; } var nextState = _bufferedStates.Peek(); if (_stateMachine.TrySetState(nextState)) { _bufferedStates.Dequeue(); Debug.Log($&#34;执行缓冲状态: {nextState}&#34;); } } }最佳实践#✅ DO（推荐做法）#合理设置超时时间 // ✅ 好：根据游戏节奏设置 _inputBuffer.Buffer(nextState, 0.3f); // 快节奏 _inputBuffer.Buffer(nextState, 0.8f); // 慢节奏每帧调用Update // ✅ 好：在Update中调用 void Update() { _inputBuffer.Update(); }检查是否已有缓冲 // ✅ 好：避免覆盖重要输入 if (!_inputBuffer.IsActive) { _inputBuffer.Buffer(state, timeout); }❌ DON&rsquo;T（避免做法）#超时时间过长 // ❌ 差：太长的缓冲时间影响手感 _inputBuffer.Buffer(state, 2.0f); // 太长！忘记调用Update // ❌ 差：不调用Update，缓冲永远不会执行 void Update() { // 忘记调用 _inputBuffer.Update(); }参考资料#📚 相关文档#FSM 主页 Changing States Weapons Sample 💡 源代码#路径: Assets/Plugins/Animancer/Utilities/FSM/ 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer FSM - Owned States 官方文档#📋 目录#概述 核心概念 实现方式 扩展方法 代码示例 参考资料 概述#Owned States（状态所有权） 允许状态持有对其父状态机的引用，无需状态预先知道状态机的存在。
&ldquo;状态可以可选地实现 IOwnedState 接口，以便在状态中使用 StateExtensions 类的扩展方法&rdquo;
核心概念#🔑 问题：状态如何切换？#// ❌ 传统方式：状态需要引用角色来访问状态机 public class WalkState : IState { private Character _character; public void DoSomething() { _character.StateMachine.TrySetState(_character.RunState); } }✅ 解决方案：Owned States#// ✅ Owned States：状态直接知道自己的状态机 public class WalkState : IOwnedState&lt;CharacterState&gt; { public StateMachine&lt;CharacterState&gt; OwnerStateMachine { get; set; } public void DoSomething() { this.TryEnterState(_runState); // 扩展方法！ } }实现方式#IOwnedState 接口#/// &lt;summary&gt; /// 状态所有权接口 /// &lt;/summary&gt; public interface IOwnedState&lt;TState&gt; where TState : class, IState { /// &lt;summary&gt; /// 拥有此状态的状态机 /// &lt;/summary&gt; StateMachine&lt;TState&gt; OwnerStateMachine { get; } }完整实现示例#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 角色控制器 /// &lt;/summary&gt; public class Character : MonoBehaviour { [SerializeField] private CharacterState.StateMachine _stateMachine; public CharacterState.StateMachine StateMachine =&gt; _stateMachine; protected virtual void Awake() { _stateMachine.InitializeAfterDeserialize(); } } /// &lt;summary&gt; /// 角色状态基类 /// 实现IOwnedState接口 /// &lt;/summary&gt; public abstract class CharacterState : StateBehaviour, IOwnedState&lt;CharacterState&gt; { [SerializeField] private Character _character; // 实现IOwnedState接口 public StateMachine&lt;CharacterState&gt; OwnerStateMachine =&gt; _character.StateMachine; // IState接口成员 public virtual bool CanEnterState =&gt; true; public virtual bool CanExitState =&gt; true; public abstract void OnEnterState(); public virtual void OnExitState() { } }扩展方法#可用的扩展方法#实现 IOwnedState 后，状态可以使用以下扩展方法：
// 状态转换 this.TryEnterState(); // 尝试进入此状态 this.TryResetState(); // 重置并进入此状态 this.ForceEnterState(); // 强制进入此状态 // 状态查询 this.IsCurrentState(); // 是否为当前状态 this.GetPreviousState(); // 获取前一个状态使用对比#不使用 IOwnedState#public class WalkState : IState { private Character _character; public void TransitionToRun() { // ❌ 需要通过角色访问状态机 _character.StateMachine.TrySetState(_character.RunState); } public bool IsWalking() { // ❌ 需要通过角色检查 return _character.StateMachine.CurrentState == this; } }使用 IOwnedState#public class WalkState : CharacterState { private RunState _runState; public void TransitionToRun() { // ✅ 直接使用扩展方法 _runState.TryEnterState(); } public bool IsWalking() { // ✅ 直接检查 return this.IsCurrentState(); } }代码示例#示例1：完整的Owned States实现#using Animancer; using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 角色控制器（使用Owned States） /// &lt;/summary&gt; public class Character : MonoBehaviour { [Header(&#34;组件&#34;)] [SerializeField] private AnimancerComponent _animancer; [Header(&#34;状态机&#34;)] [SerializeField] private CharacterState.StateMachine _stateMachine; public CharacterState.StateMachine StateMachine =&gt; _stateMachine; protected virtual void Awake() { _stateMachine.InitializeAfterDeserialize(); } } /// &lt;summary&gt; /// 角色状态基类 /// 实现IOwnedState以使用扩展方法 /// &lt;/summary&gt; public abstract class CharacterState : StateBehaviour, IOwnedState&lt;CharacterState&gt; { [SerializeField] protected Character _character; [SerializeField] protected AnimancerComponent _animancer; // 实现IOwnedState public StateMachine&lt;CharacterState&gt; OwnerStateMachine =&gt; _character.StateMachine; // IState接口 public virtual bool CanEnterState =&gt; true; public virtual bool CanExitState =&gt; true; public override void OnEnterState() { base.OnEnterState(); // 启用组件 Debug.Log($&#34;Enter: {GetType().Name}&#34;); } public override void OnExitState() { Debug.Log($&#34;Exit: {GetType().Name}&#34;); base.OnExitState(); // 禁用组件 } } /// &lt;summary&gt; /// Idle状态 /// &lt;/summary&gt; public class IdleState : CharacterState { [SerializeField] private AnimationClip _idleClip; [SerializeField] private WalkState _walkState; public override void OnEnterState() { base.OnEnterState(); _animancer.Play(_idleClip); } protected override void Update() { float input = Input.GetAxis(&#34;Vertical&#34;); if (input &gt; 0.1f) { // ✅ 使用扩展方法切换状态 _walkState.TryEnterState(); } } } /// &lt;summary&gt; /// Walk状态 /// &lt;/summary&gt; public class WalkState : CharacterState { [SerializeField] private AnimationClip _walkClip; [SerializeField] private RunState _runState; [SerializeField] private IdleState _idleState; public override void OnEnterState() { base.OnEnterState(); _animancer.Play(_walkClip); } protected override void Update() { float input = Input.GetAxis(&#34;Vertical&#34;); bool sprint = Input.GetKey(KeyCode.LeftShift); if (input &lt; 0.1f) { // ✅ 返回Idle _idleState.TryEnterState(); } else if (sprint) { // ✅ 切换到Run _runState.TryEnterState(); } } } /// &lt;summary&gt; /// Run状态 /// &lt;/summary&gt; public class RunState : CharacterState { [SerializeField] private AnimationClip _runClip; [SerializeField] private WalkState _walkState; [SerializeField] private IdleState _idleState; public override void OnEnterState() { base.OnEnterState(); _animancer.Play(_runClip); } protected override void Update() { float input = Input.GetAxis(&#34;Vertical&#34;); bool sprint = Input.GetKey(KeyCode.LeftShift); if (input &lt; 0.1f) { _idleState.TryEnterState(); } else if (!sprint) { _walkState.TryEnterState(); } } }示例2：状态查询和管理#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 使用Owned States的状态查询 /// &lt;/summary&gt; public class StateQueryExample : CharacterState { [SerializeField] private IdleState _idleState; [SerializeField] private AttackState _attackState; protected override void Update() { // ✅ 检查当前状态 if (this.IsCurrentState()) { Debug.Log(&#34;我是当前状态&#34;); } // ✅ 检查其他状态 if (_idleState.IsCurrentState()) { Debug.Log(&#34;当前是Idle状态&#34;); } // ✅ 获取前一个状态 var previous = this.GetPreviousState(); if (previous == _attackState) { Debug.Log(&#34;从攻击状态切换过来&#34;); } // ✅ 切换状态 if (Input.GetKeyDown(KeyCode.Mouse0)) { _attackState.TryEnterState(); } } }示例3：不同切换方法#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 演示不同的状态切换方法 /// &lt;/summary&gt; public class TransitionMethodsExample : CharacterState { [SerializeField] private IdleState _idleState; [SerializeField] private AttackState _attackState; [SerializeField] private DeathState _deathState; void HandleInput() { // TryEnterState：尝试进入，检查Can条件 if (Input.GetKeyDown(KeyCode.Alpha1)) { bool success = _attackState.TryEnterState(); if (success) Debug.Log(&#34;进入攻击状态&#34;); else Debug.Log(&#34;无法进入攻击状态&#34;); } // TryResetState：即使已是当前状态也重新进入 if (Input.GetKeyDown(KeyCode.Alpha2)) { _attackState.TryResetState(); } // ForceEnterState：跳过所有检查，强制进入 if (Input.GetKeyDown(KeyCode.Alpha3)) { _deathState.ForceEnterState(); } } }最佳实践#✅ DO（推荐做法）#状态基类实现IOwnedState // ✅ 好：在基类中实现 public abstract class CharacterState : StateBehaviour, IOwnedState&lt;CharacterState&gt; { public StateMachine&lt;CharacterState&gt; OwnerStateMachine =&gt; _character.StateMachine; }使用扩展方法简化代码 // ✅ 好：简洁清晰 _walkState.TryEnterState(); this.IsCurrentState();序列化状态引用 // ✅ 好：在Inspector中配置状态引用 [SerializeField] private WalkState _walkState; [SerializeField] private RunState _runState;❌ DON&rsquo;T（避免做法）#不实现IOwnedState时手动管理 // ❌ 差：不如使用IOwnedState _character.StateMachine.TrySetState(_walkState);循环依赖 // ❌ 差：状态间循环引用 public class StateA : CharacterState { [SerializeField] private StateB _stateB; } public class StateB : CharacterState { [SerializeField] private StateA _stateA; // 循环！ }参考资料#📚 相关文档#FSM 主页 State Types Changing States 💡 源代码#路径: Assets/Plugins/Animancer/Utilities/FSM/ IOwnedState.cs StateExtensions.cs 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Animancer FSM - State Types 官方文档#📋 目录#概述 状态类型选择 基础实现 内置基础类 代码示例 参考资料 概述#Animancer的状态机系统是通用的，需要定义基础状态类型作为 StateMachine&lt;TState&gt; 的泛型参数。
🔑 唯一要求#状态类必须实现 IState 接口
状态类型选择#📦 三种实现方式#类型 适用场景 优点 缺点 MonoBehaviour 需要Unity生命周期方法 可使用Update/FixedUpdate 需要附加到GameObject ScriptableObject 可复用的状态资产 可在Inspector配置 需要创建Asset文件 普通C#类 纯逻辑状态 轻量级，无开销 无Unity功能 🎯 选择建议#// 方式1：MonoBehaviour - 需要Unity生命周期 public class IdleState : StateBehaviour { void Update() { /* 每帧更新 */ } void OnTriggerEnter(Collider other) { /* 碰撞检测 */ } } // 方式2：ScriptableObject - 可复用配置 [CreateAssetMenu(menuName = &#34;States/Idle&#34;)] public class IdleStateAsset : State { [SerializeField] private float _duration; } // 方式3：普通C#类 - 纯逻辑（推荐） public class IdleState : IState { public bool CanEnterState =&gt; true; public bool CanExitState =&gt; true; public void OnEnterState() { } public void OnExitState() { } }基础实现#📝 最小实现#/// &lt;summary&gt; /// 最基础的状态实现 /// &lt;/summary&gt; public class MinimalState : IState { // 可以进入 public bool CanEnterState =&gt; true; // 可以退出 public bool CanExitState =&gt; true; // 进入状态时调用 public void OnEnterState() { Debug.Log(&#34;进入状态&#34;); } // 退出状态时调用 public void OnExitState() { Debug.Log(&#34;退出状态&#34;); } }🎨 自定义基类#推荐：&ldquo;可以简单地继承它，仅覆盖实际需要使用的成员&rdquo;
/// &lt;summary&gt; /// 自定义状态基类 /// 封装通用逻辑 /// &lt;/summary&gt; public abstract class State : IState { // 默认实现 public virtual bool CanEnterState =&gt; true; public virtual bool CanExitState =&gt; true; // 默认空实现 public virtual void OnEnterState() { } public virtual void OnExitState() { } } // 使用示例 public class IdleState : State { // 只需覆盖需要的方法 public override void OnEnterState() { Debug.Log(&#34;Idle&#34;); } }内置基础类#1. State 类#功能： 提供 IState 接口的默认实现。
/// &lt;summary&gt; /// Animancer内置基类 /// &lt;/summary&gt; public class State : IState { public virtual bool CanEnterState =&gt; true; public virtual bool CanExitState =&gt; true; public virtual void OnEnterState() { } public virtual void OnExitState() { } }使用示例：
// 继承State类 public class WalkState : State { public override void OnEnterState() { Debug.Log(&#34;开始行走&#34;); } }2. DelegateState 类#功能： 通过为接口成员分配委托来实现逻辑。
/// &lt;summary&gt; /// 委托状态 /// 使用委托实现状态逻辑 /// &lt;/summary&gt; public class DelegateState : IState { public Func&lt;bool&gt; CanEnter; public Func&lt;bool&gt; CanExit; public Action OnEnter; public Action OnExit; public bool CanEnterState =&gt; CanEnter?.Invoke() ?? true; public bool CanExitState =&gt; CanExit?.Invoke() ?? true; public void OnEnterState() =&gt; OnEnter?.Invoke(); public void OnExitState() =&gt; OnExit?.Invoke(); }使用示例：
// 使用委托配置状态 var idleState = new DelegateState { OnEnter = () =&gt; Debug.Log(&#34;进入Idle&#34;), OnExit = () =&gt; Debug.Log(&#34;退出Idle&#34;) }; var walkState = new DelegateState { CanEnter = () =&gt; speed &gt; 0.1f, // 有速度才能进入 OnEnter = () =&gt; _animancer.Play(_walkClip) }; _stateMachine.TrySetState(idleState);3. StateBehaviour 类#功能： 继承 MonoBehaviour，支持 Unity 生命周期消息。
关键特性：&ldquo;OnEnterState和OnExitState方法分别启用和禁用自身&rdquo;
/// &lt;summary&gt; /// MonoBehaviour状态基类 /// 进入时启用，退出时禁用 /// &lt;/summary&gt; public abstract class StateBehaviour : MonoBehaviour, IState { public virtual bool CanEnterState =&gt; true; public virtual bool CanExitState =&gt; true; public virtual void OnEnterState() { enabled = true; // 自动启用 } public virtual void OnExitState() { enabled = false; // 自动禁用 } // 可使用Unity生命周期方法 protected virtual void Update() { } protected virtual void FixedUpdate() { } protected virtual void OnTriggerEnter(Collider other) { } }使用示例：
/// &lt;summary&gt; /// Idle状态（MonoBehaviour实现） /// &lt;/summary&gt; public class IdleBehaviour : StateBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private AnimationClip _idleClip; public override void OnEnterState() { base.OnEnterState(); // 调用基类（启用组件） _animancer.Play(_idleClip); Debug.Log(&#34;Idle状态激活&#34;); } protected override void Update() { // 只在状态激活时执行 Debug.Log(&#34;Idle Update&#34;); } public override void OnExitState() { Debug.Log(&#34;Idle状态停用&#34;); base.OnExitState(); // 调用基类（禁用组件） } }代码示例#示例1：三种类型对比#using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// 三种状态类型对比示例 /// &lt;/summary&gt; public class StateTypesComparison : MonoBehaviour { private StateMachine&lt;IState&gt; _stateMachine; void Awake() { _stateMachine = new StateMachine&lt;IState&gt;(); // 类型1：普通C#类 var pocoState = new POCOState(); // 类型2：ScriptableObject（需要预先创建Asset） // var soState = Resources.Load&lt;ScriptableObjectState&gt;(&#34;States/Idle&#34;); // 类型3：MonoBehaviour（需要添加到GameObject） var monoState = gameObject.AddComponent&lt;MonoBehaviourState&gt;(); // 设置初始状态 _stateMachine.TrySetState(pocoState); } // 1. 普通C#类实现 public class POCOState : IState { public bool CanEnterState =&gt; true; public bool CanExitState =&gt; true; public void OnEnterState() { Debug.Log(&#34;[POCO] Enter&#34;); } public void OnExitState() { Debug.Log(&#34;[POCO] Exit&#34;); } } // 2. ScriptableObject实现 [CreateAssetMenu(menuName = &#34;States/SO State&#34;)] public class ScriptableObjectState : State { [SerializeField] private string _stateName; public override void OnEnterState() { Debug.Log($&#34;[SO] Enter: {_stateName}&#34;); } } // 3. MonoBehaviour实现 public class MonoBehaviourState : StateBehaviour { public override void OnEnterState() { base.OnEnterState(); Debug.Log(&#34;[MonoBehaviour] Enter&#34;); } protected override void Update() { // 只在状态激活时执行 Debug.Log(&#34;[MonoBehaviour] Update&#34;); } public override void OnExitState() { Debug.Log(&#34;[MonoBehaviour] Exit&#34;); base.OnExitState(); } } }示例2：DelegateState实用案例#using Animancer; using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// DelegateState实用示例 /// 快速原型设计和测试 /// &lt;/summary&gt; public class DelegateStateExample : MonoBehaviour { [SerializeField] private AnimancerComponent _animancer; [SerializeField] private AnimationClip _idleClip; [SerializeField] private AnimationClip _walkClip; private StateMachine&lt;DelegateState&gt; _stateMachine; private DelegateState _idle; private DelegateState _walk; void Awake() { _stateMachine = new StateMachine&lt;DelegateState&gt;(); // 快速创建Idle状态 _idle = new DelegateState { OnEnter = () =&gt; { Debug.Log(&#34;→ Idle&#34;); _animancer.Play(_idleClip); }, OnExit = () =&gt; Debug.Log(&#34;← Idle&#34;) }; // 快速创建Walk状态（带条件） _walk = new DelegateState { CanEnter = () =&gt; { // 只有在地面上才能行走 bool isGrounded = Physics.Raycast( transform.position, Vector3.down, 1.1f ); return isGrounded; }, OnEnter = () =&gt; { Debug.Log(&#34;→ Walk&#34;); _animancer.Play(_walkClip); }, OnExit = () =&gt; Debug.Log(&#34;← Walk&#34;) }; _stateMachine.TrySetState(_idle); } void Update() { float speed = Input.GetAxis(&#34;Vertical&#34;); if (speed &gt; 0.1f) { bool success = _stateMachine.TrySetState(_walk); if (!success) { Debug.Log(&#34;无法进入Walk状态（可能不在地面）&#34;); } } else { _stateMachine.TrySetState(_idle); } } }示例3：StateBehaviour完整示例#using Animancer; using Animancer.FSM; using UnityEngine; /// &lt;summary&gt; /// StateBehaviour完整示例 /// 展示MonoBehaviour状态的完整用法 /// &lt;/summary&gt; public class StateBehaviourExample : MonoBehaviour { private StateMachine&lt;StateBehaviour&gt; _stateMachine; void Awake() { _stateMachine = new StateMachine&lt;StateBehaviour&gt;(); // 添加状态组件 var idle = gameObject.AddComponent&lt;IdleStateBehaviour&gt;(); var patrol = gameObject.AddComponent&lt;PatrolStateBehaviour&gt;(); // 设置初始状态 _stateMachine.TrySetState(idle); } } /// &lt;summary&gt; /// Idle状态行为 /// &lt;/summary&gt; public class IdleStateBehaviour : StateBehaviour { [SerializeField] private AnimancerComponent _animancer; private float _idleTime; public override void OnEnterState() { base.OnEnterState(); _idleTime = 0f; _animancer.Play(_idleClip); Debug.Log(&#34;进入Idle&#34;); } protected override void Update() { _idleTime += Time.deltaTime; // Idle 3秒后自动切换到Patrol if (_idleTime &gt;= 3f) { var patrol = GetComponent&lt;PatrolStateBehaviour&gt;(); var fsm = GetComponent&lt;StateBehaviourExample&gt;(); // fsm._stateMachine.TrySetState(patrol); } } [SerializeField] private AnimationClip _idleClip; } /// &lt;summary&gt; /// Patrol状态行为 /// &lt;/summary&gt; public class PatrolStateBehaviour : StateBehaviour { [SerializeField] private Transform[] _waypoints; private int _currentWaypoint; public override void OnEnterState() { base.OnEnterState(); _currentWaypoint = 0; Debug.Log(&#34;开始巡逻&#34;); } protected override void Update() { if (_waypoints == null || _waypoints.Length == 0) return; // 移动到当前路径点 Transform target = _waypoints[_currentWaypoint]; transform.position = Vector3.MoveTowards( transform.position, target.position, 2f * Time.deltaTime ); // 到达后切换下一个路径点 if (Vector3.Distance(transform.position, target.position) &lt; 0.1f) { _currentWaypoint = (_currentWaypoint + 1) % _waypoints.Length; } } public override void OnExitState() { Debug.Log(&#34;结束巡逻&#34;); base.OnExitState(); } }参考资料#📚 相关文档#FSM Overview FSM Initialization Changing States 💡 源代码#路径: Assets/Plugins/Animancer/Utilities/FSM/ IState.cs State.cs DelegateState.cs StateBehaviour.cs 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+

Mecanim vs. Animancer 对比文档#📋 目录#概述 核心差异 六大优势 对比领域 兼容性 参考资料 概述#&ldquo;Animancer streamlines the animation development process by removing the need to create Animator Controllers and scripts that need to interact with each other.&rdquo;
Animancer 通过移除 Animator Controller 和脚本之间的交互需求，简化了动画开发流程。
架构差异#系统 架构方式 Mecanim 动画逻辑分散在 Controller 和脚本中 Animancer 脚本完全管理动画逻辑 核心差异#Mecanim 的工作流程#创建 Animator Controller 资产 ↓ 在 Controller 中配置状态和过渡 ↓ 创建参数 ↓ 编写脚本设置参数 ↓ Controller 根据参数自动切换状态Animancer 的工作流程#编写脚本 ↓ 直接调用 Play() 方法 ↓ 动画立即播放六大优势#Animancer 相比 Mecanim 的六个主要优势：
1. 简洁性（Simplicity）#问题：Mecanim 需要多个步骤才能播放动画
1. 创建 Animator Controller 资产 2. 创建状态 3. 分配动画 4. 创建参数 5. 创建过渡 6. 设置过渡条件 7. 编写脚本设置参数解决：Animancer 只需一行代码
_animancer.Play(_clip);2. 透明性（Transparency）#问题：Mecanim 内部逻辑不可见
无法访问源代码 无法调试内部决策过程 延迟执行导致状态不明确 解决：Animancer 提供完全透明性
Pro 版本包含完整源代码 所有操作立即生效 可以检查和记录所有内部状态 3. 适应性（Adaptability）#问题：Mecanim 强制所有动画逻辑集中在单个 Controller 中
解决：Animancer 允许灵活组织动画
按功能模块分组 按角色部位分组 按武器类型分组 4. 清晰性（Clarity）#问题：Mecanim 中脚本和 Controller 的关系不明确
查看脚本不知道需要什么 Controller 查看 Controller 不知道需要什么脚本 难以追踪参数使用情况 解决：Animancer 所有依赖都在脚本中明确定义
[SerializeField] private AnimationClip _walk; [SerializeField] private AnimationClip _run; // 一目了然需要哪些动画5. 安全性（Safety）#问题：Mecanim 依赖&quot;魔法字符串&quot;
_animator.Play(&#34;Walk&#34;); // 拼写错误只在运行时才发现 _animator.SetFloat(&#34;Speed&#34;, 5f); // 参数不存在也不会报错解决：Animancer 使用强类型引用
_animancer.Play(_walkClip); // 编译时检查 // 如果_walkClip未赋值，编译器会警告6. 可靠性（Reliability）#问题：Mecanim 的响应不可预测
命令延迟到下一帧执行 同一帧多个命令会被忽略 无法立即获取状态信息 解决：Animancer 命令立即生效
var state = _animancer.Play(_jump); Debug.Log(state.Length); // 立即获取动画长度 Debug.Log(state.IsPlaying); // 立即获取播放状态对比领域#Animancer 提供详细的实战场景对比：
1. 播放动画（Playing）#如何播放单个动画 有脚本和无脚本的方式对比 2. 等待动画（Waiting）#如何等待动画结束再执行代码 不同等待方式的对比 3. 速度和时间（Speed and Time）#如何控制动画速度 如何操作动画时间 4. 武器动画（Weapon Animations）#如何设置每个武器有自己的攻击动画 动画覆盖系统的实现 性能对比#&ldquo;Animancer can be more efficient than other systems if used correctly, though in most cases the differences are small enough not to matter either way.&rdquo;
性能数据#指标 Animancer Mecanim 差异 实例化 ~相同 ~相同 Animancer可选20-35%更快 平均帧率 快5% 基准 Animancer更优 内存占用 ~相同 ~相同 基本相当 性能建议#对大多数项目而言：
✅ 性能差异很小，不应作为主要决策因素 ✅ 开发效率比微小的性能差异更重要 ✅ 选择能让开发最轻松的方案 兼容性#混合使用#&ldquo;Animancer can play alongside Animator Controllers&rdquo;
Animancer 和 Mecanim 可以共存：
// 使用 HybridAnimancerComponent [SerializeField] private HybridAnimancerComponent _animancer; void Start() { // 播放 Animator Controller _animancer.PlayController(); } void SpecialMove() { // 临时切换到 Animancer 动画 var state = _animancer.Play(_specialClip); state.Events.OnEnd = () =&gt; { // 返回 Controller _animancer.PlayController(); }; }渐进迁移策略#第1阶段：保留现有 Controller ↓ 第2阶段：新功能使用 Animancer ↓ 第3阶段：逐步迁移旧功能 ↓ 第4阶段（可选）：完全移除 Controller快速决策指南#选择 Mecanim 的情况#✅ 已有大量 Controller 资产且运行良好 ✅ 团队不熟悉编程，依赖可视化工具 ✅ 简单项目，动画逻辑固定 选择 Animancer 的情况#✅ 新项目或可以重构的项目 ✅ 需要灵活的动画控制 ✅ 复杂的动画逻辑和状态管理 ✅ 团队有编程能力 ✅ 需要调试和优化动画系统 选择混合方案的情况#✅ 遗留项目迁移 ✅ 基础动画用 Controller，特殊动画用 Animancer ✅ 多人协作，美术用 Controller，程序用 Animancer 代码对比#示例：播放动画#Mecanim 方式：
// 1. 创建 Animator Controller 资产 // 2. 在 Controller 中创建 &#34;Walk&#34; 状态 // 3. 分配动画到状态 // 4. 可选：创建过渡和参数 // 代码中： _animator.Play(&#34;Walk&#34;); // 下一帧才会生效Animancer 方式：
// 直接在脚本中： [SerializeField] private AnimationClip _walk; void PlayWalk() { _animancer.Play(_walk); // 立即生效 }示例：等待动画结束#Mecanim 方式：
// 方式1：检查状态（需要Exit Time） IEnumerator WaitForAnimation() { _animator.Play(&#34;Attack&#34;); while (true) { var info = _animator.GetCurrentAnimatorStateInfo(0); if (info.IsName(&#34;Attack&#34;) &amp;&amp; info.normalizedTime &gt;= 1f) break; yield return null; } // 动画结束后的代码 OnAttackComplete(); }Animancer 方式：
// 方式1：End Events void PlayAttack() { var state = _animancer.Play(_attack); state.Events.OnEnd = OnAttackComplete; } // 方式2：Coroutine IEnumerator PlayAttackCoroutine() { var state = _animancer.Play(_attack); yield return state; // 等待动画结束 OnAttackComplete(); }示例：动画速度控制#Mecanim 方式：
// 1. 在 Controller 中创建 Float 参数 &#34;SpeedMultiplier&#34; // 2. 在状态的 Speed 字段设置 Parameter: SpeedMultiplier // 代码中： _animator.SetFloat(&#34;SpeedMultiplier&#34;, 1.5f);Animancer 方式：
// 直接设置： var state = _animancer.Play(_walk); state.Speed = 1.5f; // 或通过 Transition 预设： _walkTransition.Speed = 1.5f; _animancer.Play(_walkTransition);总结#Mecanim 的优势#✅ 可视化编辑器 ✅ 无需编程知识 ✅ Unity 官方支持 Mecanim 的劣势#❌ 配置复杂 ❌ 调试困难 ❌ 灵活性差 ❌ 维护成本高 Animancer 的优势#✅ 代码驱动，灵活强大 ✅ 调试简单 ✅ 维护方便 ✅ 性能略优 Animancer 的劣势#❌ 需要编程能力 ❌ 需要购买（有免费 Lite 版） ❌ 无可视化状态机编辑器 参考资料#📚 详细对比文档#animancer-why - 六大优势详解 animancer-simplicity animancer-transparency animancer-adaptability animancer-clarity animancer-safety animancer-reliability 🔍 实战对比#animancer-playing animancer-waiting animancer-speedandtime animancer-weaponanimations ⚡ 性能分析#animancer-performance 📖 术语表#animancer-glossary 文档版本: 1.0 最后更新: 2025-12-25 适用 Animancer 版本: 8.0+
